<script setup>
import { ref, computed, onMounted } from 'vue';
import { Button } from '@components';
const formychat = formychat_admin_vars || {}

import { useUpgrade } from '@store/Upgrade.js';
const $upgrade = useUpgrade();

const currentTime = ref(new Date());

// Read SDK data directly in computed — WPPOOL_Plugins is available by the time
// user clicks a locked feature (modal is never shown on initial page load).
const sdkCampaign = computed(() => {
    return window.WPPOOL_Plugins?.plugins?.social_contact_form || {};
})

const isCampaign = computed(() => {
    const sdk = sdkCampaign.value;
    if (!sdk.background_image || !sdk.from || !sdk.to) return false;
    const now = new Date();
    return now > new Date(sdk.from) && now < new Date(sdk.to);
})

const timer = computed(() => {
    const now = currentTime.value.getTime();
    const sdk = sdkCampaign.value;
    let end_date = new Date(sdk.to).getTime();

    // Recurring cycle: restart every sdk.repeat ms from sdk.from_ms, capped at sdk.to_ms.
    if (sdk.repeat && sdk.from_ms && sdk.to_ms) {
        const cycles = Math.floor((now - sdk.from_ms) / sdk.repeat) + 1;
        end_date = Math.min(sdk.from_ms + cycles * sdk.repeat, sdk.to_ms);
    }

    const diff = Math.max(0, end_date - now);

    const days = Math.floor(diff / (1000 * 60 * 60 * 24));
    const hours = Math.floor((diff % (1000 * 60 * 60 * 24)) / (1000 * 60 * 60));
    const minutes = Math.floor((diff % (1000 * 60 * 60)) / (1000 * 60));
    const seconds = Math.floor((diff % (1000 * 60)) / 1000);

    return { days, hours, minutes, seconds }
})

const bg_image = computed(() => {
    if (isCampaign.value) return sdkCampaign.value.background_image;
    return null;
})

const btn_text = computed(() => {
    if (isCampaign.value) return sdkCampaign.value.button_text || 'Grab Your Deals!';
    return 'GET PREMIUM';
})

// Campaign CTA colors. "!important" is needed because Tailwind is built with important: true.
const campaignBtnStyle = computed(() => {
    if (!isCampaign.value) return null;
    const bg = sdkCampaign.value.color || '#FFD23F';
    return {
        backgroundColor: `${bg} !important`,
        borderColor: `${bg} !important`,
        color: '#111111 !important',
    };
})

const btn_link = computed(() => {
    if (isCampaign.value) return sdkCampaign.value.button_link;
    return 'https://lnk.wppool.dev/bTUp5Cu';
})

onMounted(() => {
    document.addEventListener('click', (e) => {
        if (e.target.closest('.formychat-locked')) {
            e.preventDefault();
            $upgrade.show()
        }
    });

    setInterval(() => {
        currentTime.value = new Date();
    }, 1000);
})
</script>
<template>
    <!-- Teleported to <body> so the backdrop covers the whole screen, WP admin bar and menu included. -->
    <Teleport to="body" v-if="!formychat.is_premium">
        <transition name="fast-fade">
            <div v-if="$upgrade.isShown" class="formychat-upgrade-modal fixed inset-0 flex items-center justify-center p-4" style="z-index: 100000">
                <div @click="$upgrade.hide" class="absolute inset-0" style="background: rgba(15, 23, 42, .5)"></div>
                <div class="relative w-full max-w-lg flex items-center justify-center">
                    <div
                        class="relative w-full max-w-lg flex flex-col gap-4 h-auto rounded-xl shadow-lg drop-shadow-lg">
                        <img v-if="bg_image" :src="bg_image" class="h-full w-auto mx-auto">
                        <img v-else :src="Image('upgrade.png')" class="h-full w-auto mx-auto">
                        <!-- close  -->
                        <svg @click="$upgrade.hide" xmlns="http://www.w3.org/2000/svg"
                            class="h-6 w-6 text-gray-500 absolute hover:scale-125 transition right-4 top-4 cursor-pointer"
                            fill="none" viewBox="0 0 24 24" stroke="currentColor">
                            <path stroke-linecap="round" stroke-linejoin="round" stroke-width="2"
                                d="M6 18L18 6M6 6l12 12" />
                        </svg>
                        <div class="absolute bottom-4 left-1/2 -translate-x-1/2">
                            <!-- counter  -->
                            <div v-if="isCampaign" class="flex items-center justify-center gap-3 pb-7">
                                <div
                                    class="w-20 h-20 bg-gray-50 bg-opacity-[.05] rounded-lg text-xs uppercase text-gray-300 flex flex-col gap-2 items-center justify-center">
                                    <span class="text-4xl tracking-wider font-medium text-white">{{timer.days}}</span> <span>DAYS</span>
                                </div>
                                <div
                                    class="w-20 h-20 bg-gray-50 bg-opacity-[.05] rounded-lg text-xs uppercase text-gray-300 flex flex-col gap-2 items-center justify-center">
                                    <span class="text-4xl tracking-wider font-medium text-white">{{timer.hours}}</span> <span>HOURS</span>
                                </div>
                                <div
                                    class="w-20 h-20 bg-gray-50 bg-opacity-[.05] rounded-lg text-xs uppercase text-gray-300 flex flex-col gap-2 items-center justify-center">
                                    <span class="text-4xl tracking-wider font-medium text-white">{{timer.minutes}}</span> <span>MINUTES</span>
                                </div>
                                <div
                                    class="w-20 h-20 bg-gray-50 bg-opacity-[.05] rounded-lg text-xs uppercase text-gray-300 flex flex-col gap-2 items-center justify-center">
                                    <span class="text-4xl tracking-wider font-medium text-white">{{timer.seconds}}</span> <span>SECONDS</span>
                                </div>
                            </div>
                            <Button class="font-medium px-6 h-12 text-base text-center flex items-center justify-center" a
                            :href="btn_link"
                            :style="campaignBtnStyle"
                                target="_blank">{{ btn_text }}</Button>
                            <div class="text-center mt-4">
                                <a href="https://lnk.wppool.dev/tBWyyUk"
                                    class="text-indigo-200 cursor-pointer hover:text-white transition text-base"
                                    target="_blank">Try a free demo</a>
                            </div>
                        </div>
                    </div>
                </div>
            </div>
        </transition>
    </Teleport>
</template>
