<script setup>
/**
 * Channel icon and color, in each channel's Settings panel.
 *
 * WhatsApp keeps its icon in `icon.image_url` (and `icon.image_url_custom`), as before.
 * Telegram uses `telegram.icon_url`. Background colors live in `{channel}.icon_color` (empty = brand color),
 * logo glyph colors in `{channel}.glyph_color` (empty = white).
 * Upload and any (custom) color are FormyChat Ultimate features; the preset colors are free.
 *
 * @since 2.16.0
 */
import { computed } from 'vue';
import { useWidgets } from '@store/widgets';
import { LockedHover, ChannelGlyph } from '@components';
import { useTranslation } from '../../../composables/useTranslation';
import { CHANNEL_COLORS, CHANNEL_COLOR_PRESETS, CHANNEL_GLYPH_COLOR, CHANNEL_GLYPH_PRESETS, isHexColor, savedChannelImage } from '../../../utility/channels';

const props = defineProps({
    channel: { type: String, required: true },
})

const $widget = useWidgets();
const { t } = useTranslation();

const isLocked = !window.formychat_admin_vars?.is_premium
const publicUrl = window.formychat_admin_vars?.public || ''
const config = computed(() => $widget.currentWidget?.config || {})
const settings = computed(() => config.value[props.channel] || {})
const brand = computed(() => CHANNEL_COLORS[props.channel] || CHANNEL_COLORS.whatsapp)

// The uploaded image, or '' while the channel's own logo is used.
const image = computed(() => savedChannelImage(config.value, props.channel))

const savedHex = key => isHexColor(settings.value[key]) ? settings.value[key] : ''
const shownColor = computed(() => savedHex('icon_color') || brand.value)
const shownGlyphColor = computed(() => savedHex('glyph_color') || CHANNEL_GLYPH_COLOR)

const setColor = (key, value) => {
    if (!config.value[props.channel]) return
    config.value[props.channel][key] = isHexColor(value) ? value : ''
}

// The two color rows share one markup: background (`icon_color`) and logo glyph (`glyph_color`).
const colorRows = computed(() => [
    { key: 'icon_color', label: t('channel_background_label'), fallback: brand.value, presets: CHANNEL_COLOR_PRESETS },
    { key: 'glyph_color', label: t('channel_glyph_color_label'), fallback: CHANNEL_GLYPH_COLOR, presets: [CHANNEL_GLYPH_PRESETS[0], brand.value, ...CHANNEL_GLYPH_PRESETS.slice(1)] },
].map((row) => {
    const value = savedHex(row.key)
    const same = preset => value.toLowerCase() === preset.toLowerCase()
    return { ...row, value, same, isCustom: !!value && !row.presets.some(same) }
}))

const setImage = (url) => {
    if (props.channel === 'whatsapp') {
        if (!config.value.icon) return
        config.value.icon.image_url = url
        config.value.icon.image_url_custom = url
        return
    }
    if (config.value[props.channel]) config.value[props.channel].icon_url = url
}

// Locked: the click reaches the upgrade prompt through .formychat-locked.
const upload = () => {
    if (isLocked || typeof wp === 'undefined' || !wp.media?.editor) return
    wp.media.editor.send.attachment = (attrs, attachment) => {
        if (attachment?.url) setImage(attachment.url)
    }
    wp.media.editor.open()
}

// Back to the channel's own logo. The WhatsApp upload stays remembered in `icon.image_url_custom`.
const reset = () => {
    if (props.channel === 'whatsapp') {
        if (config.value.icon) config.value.icon.image_url = publicUrl + 'images/whatsapp.svg'
        return
    }
    if (config.value[props.channel]) config.value[props.channel].icon_url = ''
}

// Color circles: all the same size; the selected one gets an indigo ring with a white gap.
const dot = 'w-7 h-7 rounded-full shrink-0 ring-offset-2 transition outline-none focus-visible:ring-2 focus-visible:ring-indigo-500'
const on = 'ring-2 ring-indigo-600'
const off = 'ring-1 ring-black/10 hover:scale-110'
const rainbow = 'conic-gradient(#EF4444, #F59E0B, #22C55E, #0EA5E9, #6366F1, #EC4899, #EF4444)'
</script>
<template>
    <div class="flex flex-col gap-4">
        <!-- Icon  -->
        <div class="flex flex-col gap-2">
            <h4 class="m-0 text-[13px] font-semibold text-slate-900">{{ t('channel_icon_label') }}</h4>
            <div class="flex items-center gap-2">
                <span class="w-11 h-11 rounded-full grid place-items-center shrink-0 overflow-hidden shadow-sm"
                    :style="image ? {} : { background: shownColor }">
                    <img v-if="image" :src="image" class="w-full h-full object-cover" alt="">
                    <ChannelGlyph v-else :channel="channel" :color="shownGlyphColor" class="w-6 h-6" />
                </span>
                <!-- Ultimate: faded at rest; on hover / focus the Ultimate pill shows  -->
                <LockedHover :locked="isLocked" tag="span" class="inline-flex">
                    <button type="button"
                        class="inline-flex items-center h-8 px-3 rounded-lg border border-slate-200 bg-white text-[13px] font-medium text-slate-700 hover:border-slate-300 transition"
                        @click="upload">{{ t('upload') }}</button>
                </LockedHover>
                <button type="button"
                    class="inline-flex items-center h-8 px-3 rounded-lg text-[13px] font-medium text-slate-500 hover:text-slate-800 hover:bg-slate-100 disabled:opacity-40 disabled:pointer-events-none transition"
                    :disabled="!image" @click="reset">{{ t('reset') }}</button>
            </div>
        </div>

        <!-- Background and icon color; an uploaded image has its own colors  -->
        <template v-if="!image">
            <div v-for="row in colorRows" :key="row.key" class="flex flex-col gap-2">
                <h4 class="m-0 text-[13px] font-semibold text-slate-900">{{ row.label }}</h4>
                <div class="flex flex-wrap items-center gap-2" role="group" :aria-label="row.label">
                    <!-- One row of equal circles: default, presets, then any color -->
                    <!-- Default: the first circle; white (icon color) keeps a faint inner ring so it stays visible -->
                    <button type="button"
                        :class="[dot, !row.value ? on : off, row.key === 'glyph_color' ? 'shadow-[inset_0_0_0_1px_rgba(0,0,0,0.1)]' : '']"
                        :style="{ background: row.fallback }" :title="t('default')" :aria-label="t('default')"
                        :aria-pressed="!row.value ? 'true' : 'false'" @click="setColor(row.key, '')"></button>
                    <button v-for="preset in row.presets" :key="preset" type="button"
                        :class="[dot, row.same(preset) ? on : off]"
                        :style="{ background: preset }" :title="preset" :aria-label="preset"
                        :aria-pressed="row.same(preset) ? 'true' : 'false'" @click="setColor(row.key, preset)"></button>
                    <!-- Any color: FormyChat Ultimate. A color saved earlier still shows; locked, clicks open the upgrade prompt. -->
                    <LockedHover :locked="isLocked" variant="tip" tag="label" :title="t('custom_color')"
                        :class="[dot, 'cursor-pointer focus-within:ring-2 focus-within:ring-indigo-500', row.isCustom ? on : off]">
                        <span class="block w-full h-full rounded-full" :style="{ background: row.isCustom ? row.value : rainbow }">
                            <input type="color" class="absolute inset-0 w-full h-full opacity-0 cursor-pointer" :class="{ 'pointer-events-none': isLocked }"
                                :disabled="isLocked" :aria-label="t('custom_color')"
                                :value="row.value || row.fallback" @input="setColor(row.key, $event.target.value)">
                        </span>
                    </LockedHover>
                </div>
            </div>
        </template>
    </div>
</template>
