<script setup>
import { computed, ref, watch } from 'vue';
import { useWidgets } from '@store/widgets';
import { Select, Toggle } from '@components';
import { useTranslation } from '../../../composables/useTranslation';
import ChannelIconField from './ChannelIconField.vue';
import { cleanTelegramUsername, isValidTelegramUsername, buildTelegramUrl } from '../../../utility/channels';

const props = defineProps({
    // 'primary': who visitors reach (always visible). 'advanced': the card's Settings panel.
    section: { type: String, default: 'primary' },
})

const $widget = useWidgets();
const { t } = useTranslation();

const telegram = computed(() => $widget.currentWidget?.config?.telegram || {})
const showHelp = ref(false)

// Clean pasted links (@name, t.me/name) once the admin leaves the field.
const cleanUsername = () => {
    telegram.value.username = cleanTelegramUsername(telegram.value.username)
    $widget.errors.telegram_username = !!telegram.value.username && !isValidTelegramUsername(telegram.value.username)
}

const usernameError = computed(() => $widget.errors.telegram_username)
// Same rule and live red state as the WhatsApp number: digits only, 7 to 15.
const phoneError = computed(() => !$widget.isValidPhone(String(telegram.value.phone || '')) || !!$widget.errors.telegram_phone)

const testUrl = computed(() => {
    const value = telegram.value
    if (value.mode === 'phone') {
        return $widget.isValidPhone(String(value.phone || '')) ? buildTelegramUrl(value, t('test_message')) : ''
    }
    const username = cleanTelegramUsername(value.username)
    return isValidTelegramUsername(username) ? buildTelegramUrl({ ...value, username }, t('test_message')) : ''
})

const setMode = (mode) => {
    telegram.value.mode = mode
    $widget.errors.telegram_username = false
    $widget.errors.telegram_phone = false
}

const modes = computed(() => ({ username: t('tab_username'), phone: t('tab_phone') }))

/**
 * Fill an empty dial code like WhatsApp does: the geolocated code.
 *
 * Awaits the resolver so a lookup that finished before mount is not missed,
 * and re-reads the config afterwards in case the widget changed meanwhile.
 */
const applyCountryCode = async () => {
    const config = $widget.currentWidget?.config?.telegram;

    if (!config || config.country_code) {
        return;
    }

    const detected = await window.formychat_country_code_ready;
    const current = $widget.currentWidget?.config?.telegram;

    if (!current || current.country_code) {
        return;
    }

    current.country_code = String(detected || window.formychat_country_code || '44');
}

// The widget can load or be swapped after mount, so react to the field being empty.
watch(
    () => [$widget.currentWidget?.config?.telegram, $widget.currentWidget?.config?.telegram?.country_code],
    ([config, code]) => {
        if (config && !code) {
            applyCountryCode();
        }
    },
    { immediate: true }
);
</script>
<template>
    <!-- Primary: who visitors reach  -->
    <div v-if="props.section === 'primary'" class="flex flex-col gap-2.5 max-w-xl">
        <div class="inline-flex w-fit rounded-lg bg-slate-100 p-0.5" role="tablist" :aria-label="t('telegram_contact_by')">
            <button v-for="(label, mode) in modes" :key="mode" type="button" role="tab"
                class="h-7 px-3 rounded-md text-[13px] font-medium transition"
                :class="(telegram.mode || 'username') === mode ? 'bg-white text-slate-900 shadow-sm' : 'text-slate-500 hover:text-slate-700'"
                :aria-selected="(telegram.mode || 'username') === mode ? 'true' : 'false'" @click="setMode(mode)">{{ label }}</button>
        </div>

        <!-- Username  -->
        <template v-if="telegram.mode !== 'phone'">
            <div class="flex items-center h-11 rounded-xl border bg-white transition focus-within:ring-4"
                :class="usernameError ? 'border-red-400 focus-within:ring-red-500/10' : 'border-slate-200 hover:border-slate-300 focus-within:border-indigo-500 focus-within:ring-indigo-500/10'">
                <span class="pl-3.5 pr-1 text-sm text-slate-400 select-none">t.me/</span>
                <input name="telegram_username" v-model="telegram.username" type="text" autocomplete="off" spellcheck="false"
                    class="formychat-bare-input min-w-0"
                    :placeholder="t('telegram_username_placeholder')" :aria-invalid="usernameError ? 'true' : 'false'"
                    @blur="cleanUsername" @keydown="$widget.errors.telegram_username = false">
                <a :href="testUrl || undefined" target="_blank" rel="noopener noreferrer" :title="testUrl ? t('test_link_hint') : ''"
                    class="formychat-test-btn mr-1.5" :class="{ 'is-disabled': !testUrl }" :aria-disabled="testUrl ? 'false' : 'true'">
                    {{ t('test_short') }}
                    <svg viewBox="0 0 24 24" class="w-3.5 h-3.5" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M7 17 17 7" /><path d="M7 7h10v10" /></svg>
                </a>
            </div>
            <span v-if="usernameError" class="text-xs text-red-600">{{ t('telegram_username_error') }}</span>
            <button type="button" class="text-xs text-slate-500 hover:text-indigo-600 w-fit underline decoration-dotted underline-offset-4" :aria-expanded="showHelp ? 'true' : 'false'" @click="showHelp = !showHelp">{{ t('where_do_i_find_this') }}</button>
            <p v-if="showHelp" class="m-0 text-xs text-slate-600 bg-slate-50 border border-slate-200 rounded-lg p-3 leading-relaxed">{{ t('telegram_username_help') }}</p>
        </template>

        <!-- Phone  -->
        <template v-else>
            <div class="formychat-tg-phone-row flex items-center gap-2">
                <Select :options="$widget.contents.countries" v-model="telegram.country_code" :cursor="false"
                    class="w-24 shrink-0" size="w-24" :placeholder="t('select')" white teleport
                    dropdown-anchor-selector=".formychat-tg-phone-row" :dropdown-min-width="360" :excerpt="120" />
                <div class="flex-1 min-w-0 flex items-center h-11 rounded-xl border bg-white transition focus-within:ring-4"
                    :class="phoneError ? 'border-red-400 focus-within:ring-red-500/10' : 'border-slate-200 hover:border-slate-300 focus-within:border-indigo-500 focus-within:ring-indigo-500/10'">
                    <input name="telegram_phone" v-model="telegram.phone" type="tel" autocomplete="off"
                        class="formychat-bare-input min-w-0 !px-3.5" :aria-invalid="phoneError ? 'true' : 'false'"
                        :placeholder="t('telegram_number_placeholder')" @keydown="$widget.errors.telegram_phone = false">
                    <svg v-if="phoneError && telegram.phone" viewBox="0 0 24 24" class="w-4 h-4 shrink-0 mr-2 text-red-500" fill="currentColor" :aria-label="t('valid_telegram_number_error')"><path d="M10.29 3.86 1.82 18a2 2 0 0 0 1.71 3h16.94a2 2 0 0 0 1.71-3L13.71 3.86a2 2 0 0 0-3.42 0ZM12 9a1 1 0 0 1 1 1v4a1 1 0 1 1-2 0v-4a1 1 0 0 1 1-1Zm0 8.5a1.25 1.25 0 1 1 0-2.5 1.25 1.25 0 0 1 0 2.5Z" /></svg>
                    <a :href="testUrl || undefined" target="_blank" rel="noopener noreferrer" :title="testUrl ? t('test_link_hint') : ''"
                        class="formychat-test-btn mr-1.5" :class="{ 'is-disabled': !testUrl }" :aria-disabled="testUrl ? 'false' : 'true'">
                        {{ t('test_short') }}
                        <svg viewBox="0 0 24 24" class="w-3.5 h-3.5" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M7 17 17 7" /><path d="M7 7h10v10" /></svg>
                    </a>
                </div>
            </div>
            <span v-if="phoneError && telegram.phone" class="text-xs text-red-600">{{ t('valid_telegram_number_error') }}</span>
            <p class="m-0 text-xs text-amber-800 bg-amber-50 border border-amber-200/70 rounded-lg p-2.5 leading-relaxed">{{ t('telegram_phone_warning') }}</p>
        </template>
    </div>

    <!-- Advanced: inside the Settings panel  -->
    <template v-else>
        <!-- Channel icon and color (2.16.0), first: it is what visitors see  -->
        <ChannelIconField channel="telegram" />

        <div class="flex flex-col gap-4">
            <h4 class="m-0 text-[13px] font-semibold text-slate-900">{{ t('behaviors') }}</h4>
            <Toggle v-model="telegram.redirect_after_submit" locked :hints="t('after_submit_hint_telegram')">{{ t('after_submit_redirect_telegram') }}</Toggle>
            <Toggle v-model="telegram.new_tab" :hints="t('open_telegram_new_tab_hint')">{{ t('open_telegram_new_tab') }}</Toggle>
            <Toggle v-model="telegram.web_fallback" :hints="t('telegram_web_fallback_hint')">{{ t('telegram_web_fallback') }}</Toggle>
        </div>

        <!-- Planned, shown so admins know what is coming  -->
        <div class="flex flex-col gap-2.5">
            <h4 class="m-0 text-[13px] font-semibold text-slate-900">{{ t('planned_features') }}</h4>
            <div class="flex flex-wrap gap-2">
                <span v-for="key in ['telegram_planned_agents', 'telegram_planned_groups', 'telegram_planned_alerts']" :key="key"
                    class="inline-flex items-center gap-2 h-7 pl-3 pr-1 rounded-full border border-slate-200 bg-white text-xs text-slate-600">
                    {{ t(key) }}
                    <span class="text-[10px] font-semibold uppercase tracking-wide px-2 h-5 inline-flex items-center rounded-full bg-indigo-50 text-indigo-600">{{ t('upcoming') }}</span>
                </span>
            </div>
        </div>
    </template>
</template>
