<script setup>
/**
 * Wrapper for an item that needs FormyChat Ultimate.
 *
 * At rest the item looks like any other option, in full color. On hover or keyboard focus a
 * compact Ultimate pill shows: centred on cards ('mid', which fade a little so the pill reads),
 * above small round items ('tip'). Touch screens (no hover) get a tiny lock in the corner instead.
 * The click still reaches the upgrade prompt through .formychat-locked.
 *
 * Cards with a caption under the frame can move the pill onto the frame with the
 * CSS variable --formychat-lh-y (e.g. style="--formychat-lh-y: -11px").
 *
 * Attributes and listeners (role, tabindex, @click...) go to the root element.
 *
 * @since 2.16.0
 */
import { useTranslation } from '@composables/useTranslation';

const { t } = useTranslation();

defineProps({
    locked: { type: Boolean, default: false },
    // 'mid': pill in the centre (cards). 'tip': pill above, like a tooltip (small round items).
    variant: { type: String, default: 'mid' },
    tag: { type: String, default: 'div' },
    // Pill text; defaults to "Ultimate". Pass another label (e.g. "Upcoming") with :upgrade="false".
    text: { type: String, default: '' },
    // false: disabled look and pill only, no lock icon and no upgrade prompt on click.
    upgrade: { type: Boolean, default: true },
})
</script>

<template>
    <component :is="tag" class="formychat-lh"
        :class="[{ 'formychat-lh-locked': locked, 'formychat-locked': locked && upgrade }, 'formychat-lh-' + variant]">
        <slot />
        <template v-if="locked">
            <span class="formychat-lh-badge" aria-hidden="true">
                <span class="formychat-lh-pill" :class="{ 'formychat-lh-pill-plain': !upgrade }">
                    <svg v-if="upgrade" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.6" stroke-linecap="round" stroke-linejoin="round">
                        <rect x="4.5" y="10.5" width="15" height="10.5" rx="2.5" fill="currentColor" stroke="none" />
                        <path d="M8 10.5V7.5a4 4 0 0 1 8 0v3" />
                    </svg>
                    <span>{{ text || t('ultimate') }}</span>
                </span>
            </span>
            <span class="formychat-lh-touch" aria-hidden="true">
                <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.6" stroke-linecap="round" stroke-linejoin="round">
                    <rect x="4.5" y="10.5" width="15" height="10.5" rx="2.5" fill="currentColor" stroke="none" />
                    <path d="M8 10.5V7.5a4 4 0 0 1 8 0v3" />
                </svg>
            </span>
        </template>
    </component>
</template>

<style>
.formychat-lh {
    position: relative;
}

/* At rest the item looks like any other option; only hover or focus shows it needs Ultimate. */
.formychat-lh-locked > :not(.formychat-lh-badge):not(.formychat-lh-touch) {
    transition: opacity .2s ease;
}

/* Pill. */
.formychat-lh-badge {
    position: absolute;
    z-index: 20;
    left: 50%;
    display: flex;
    pointer-events: none;
    opacity: 0;
    transition: opacity .16s ease, transform .2s cubic-bezier(.2, .8, .3, 1.2);
}

.formychat-lh-pill {
    display: inline-flex;
    align-items: center;
    gap: 4px;
    height: 20px;
    padding: 0 8px 0 6px;
    border-radius: 9999px;
    background: #4F46E5;
    color: #fff;
    font-size: 11px;
    font-weight: 600;
    line-height: 1;
    letter-spacing: .01em;
    white-space: nowrap;
    box-shadow: 0 0 0 1.5px #fff, 0 6px 14px -4px rgba(67, 56, 202, .55);
}

.formychat-lh-pill-plain {
    padding: 0 8px;
    background: #334155;
    box-shadow: 0 0 0 1.5px #fff, 0 6px 14px -4px rgba(15, 23, 42, .4);
}

.formychat-lh-pill svg {
    width: 10px;
    height: 10px;
    flex-shrink: 0;
    margin-top: -1px;
}

.formychat-lh-mid > .formychat-lh-badge {
    top: calc(50% + var(--formychat-lh-y, 0px));
    transform: translate(-50%, -50%) translateY(4px) scale(.94);
}

.formychat-lh-tip > .formychat-lh-badge {
    bottom: calc(100% + 6px);
    transform: translate(-50%, 4px) scale(.94);
}

.formychat-lh-touch {
    display: none;
}

/* Revealed state: hover (mouse) or keyboard focus. */
@media (hover: hover) {
    /* Cards fade a little so the pill on top of them reads; small items keep their colors. */
    .formychat-lh-mid.formychat-lh-locked:hover > :not(.formychat-lh-badge):not(.formychat-lh-touch) {
        opacity: .55;
    }

    .formychat-lh-locked:hover > .formychat-lh-badge {
        opacity: 1;
    }

    .formychat-lh-mid.formychat-lh-locked:hover > .formychat-lh-badge {
        transform: translate(-50%, -50%) scale(1);
    }

    .formychat-lh-tip.formychat-lh-locked:hover > .formychat-lh-badge {
        transform: translate(-50%, 0) scale(1);
    }
}

.formychat-lh-mid.formychat-lh-locked:focus-visible > :not(.formychat-lh-badge):not(.formychat-lh-touch) {
    opacity: .55;
}

.formychat-lh-locked:focus-visible > .formychat-lh-badge {
    opacity: 1;
}

.formychat-lh-mid.formychat-lh-locked:focus-visible > .formychat-lh-badge {
    transform: translate(-50%, -50%) scale(1);
}

.formychat-lh-tip.formychat-lh-locked:focus-visible > .formychat-lh-badge {
    transform: translate(-50%, 0) scale(1);
}

/* Touch: no hover, so a small lock marks the item. */
@media (hover: none) {
    .formychat-lh-touch {
        position: absolute;
        z-index: 5;
        top: 6px;
        right: 6px;
        display: grid;
        place-items: center;
        width: 18px;
        height: 18px;
        border-radius: 9999px;
        background: #fff;
        color: #4F46E5;
        box-shadow: 0 0 0 1px #E2E8F0, 0 1px 2px rgba(15, 23, 42, .08);
        pointer-events: none;
    }

    .formychat-lh-tip > .formychat-lh-touch {
        top: -4px;
        right: -4px;
        width: 15px;
        height: 15px;
    }

    .formychat-lh-touch svg {
        width: 9px;
        height: 9px;
    }
}

@media (prefers-reduced-motion: reduce) {
    .formychat-lh-badge,
    .formychat-lh-locked > :not(.formychat-lh-badge):not(.formychat-lh-touch) {
        transition: none;
    }
}
</style>
