<script setup>
/**
 * Channel name and description, in each channel's Settings panel (2+ channels).
 *
 * Name: shown next to the channel's icon in every widget style. The field opens with the name
 * visitors see now. Clearing it hides the name next to floating icons; list rows then show the
 * channel's own name, so no row is a bare icon. Saved in `{channel}.list_label`; clearing also
 * saves `{channel}.show_label: false`.
 *
 * Description: the line under the name in List, Bubble menu and Chat window (`{channel}.list_sub`).
 * While it is edited, the preview shows the list with descriptions, whatever the chosen style.
 *
 * @since 2.16.0
 */
import { computed, onBeforeUnmount } from 'vue';
import { useWidgets } from '@store/widgets';
import { Text } from '@components';
import { useTranslation } from '../../../composables/useTranslation';
import { CHANNEL_NAMES, channelLabel, setChannelLabel } from '../../../utility/channels';

const props = defineProps({
    channel: { type: String, required: true },
})

const $widget = useWidgets();
const { t } = useTranslation();

const settings = computed(() => $widget.currentWidget?.config?.[props.channel] || {})
const name = computed({
    get: () => channelLabel($widget.currentWidget?.config, props.channel),
    set: value => setChannelLabel($widget.currentWidget?.config, props.channel, value),
})
const description = computed({
    get: () => settings.value.list_sub || '',
    set: value => { if ($widget.currentWidget?.config?.[props.channel]) $widget.currentWidget.config[props.channel].list_sub = value },
})
const id = key => `formychat-channel-${key}-${props.channel}`

// Editing: the preview opens the channel list and marks this channel; for the description it
// also shows the list with descriptions.
const focus = (peek) => {
    $widget.previewFocus = props.channel
    $widget.previewPeek = peek
}
const blur = () => {
    $widget.previewFocus = ''
    $widget.previewPeek = false
}
// Leaving the tab never fires focusout, so drop the preview marks here.
onBeforeUnmount(blur)
</script>
<template>
    <div class="flex flex-col gap-4 max-w-md">
        <div class="flex flex-col gap-2" @focusin="focus(false)" @focusout="blur">
            <!-- Same heading style as Icon / Background below -->
            <label :for="id('name')" class="m-0 text-[13px] font-semibold text-slate-900">{{ t('channel_list_label') }}</label>
            <Text v-model="name" :id="id('name')" :placeholder="t('channel_name_empty')" :aria-label="t('channel_list_label') + ' ' + CHANNEL_NAMES[channel]" white />
        </div>
        <div class="flex flex-col gap-2" @focusin="focus(true)" @focusout="blur">
            <label :for="id('description')" class="m-0 text-[13px] font-semibold text-slate-900">{{ t('channel_list_sub') }}</label>
            <Text v-model="description" :id="id('description')" :placeholder="t('channel_sub_' + channel)" :aria-label="t('channel_list_sub') + ' ' + CHANNEL_NAMES[channel]" white />
        </div>
    </div>
</template>
