<script setup>
/**
 * Widget style card thumbnail: a 136 x 136 drawing of the page corner with the launcher
 * and its open channel list. Few, large shapes so every style reads at a glance.
 * Uses the widget's own channels and launcher color. Display only (ignores clicks).
 *
 * @since 2.16.0
 */
import { computed } from 'vue';
import { CHANNEL_COLORS } from '../../../utility/channels';

const props = defineProps({
    // stack, row, card, grid, menu, bubble, chat, corner.
    type: { type: String, default: 'stack' },
    left: { type: Boolean, default: false },
    accent: { type: String, default: '#4F46E5' },
    // [{ key, color, glyph, image }].
    channels: { type: Array, default: () => [] },
    // Launcher shape: circle or squircle.
    launcherShape: { type: String, default: 'circle' },
})

const S = 136
const uid = Math.random().toString(36).slice(2, 8)
const publicUrl = window.formychat_admin_vars?.public || ''

// Three channels so each style reads fully: the widget's own, then a neutral sample.
const SAMPLE = { key: 'sample', color: '#94A3B8', glyph: '' }
const list = computed(() => {
    let given = (props.channels || []).filter(Boolean).slice(0, 3)
    if (!given.length) given = ['whatsapp', 'telegram'].map(key => ({ key, color: CHANNEL_COLORS[key], glyph: publicUrl + `images/${key}-glyph.svg` }))
    while (given.length < 3) given = [...given, SAMPLE]
    return given
})

// Mirror for a widget on the left.
const X = (x, w = 0) => (props.left ? S - x - w : x)
const tint = (hex, a) => (/^#[0-9a-f]{6}$/i.test(hex || '') ? hex + a : hex)

// Launcher in the corner, 12px from the edges.
const L = { cx: 112, cy: 112, r: 12 }

const shapes = computed(() => {
    const ch = list.value
    const accent = props.accent
    const out = []
    // Left position: floating icons mirror, but a panel only moves; inside it the rows keep
    // the icon on the left and the text on the right, as on the site.
    const floating = ['stack', 'row', 'corner'].includes(props.type)
    const shift = props.left && props.type === 'menu' ? -16 : 0
    const at = (x, w = 0) => (floating ? X(x, w) : x + shift)
    const rect = (x, y, w, h, fill, rx = 2, extra = {}) => out.push({ tag: 'rect', x: at(x, w), y, width: w, height: h, rx, fill, ...extra })
    const circle = (cx, cy, r, fill, extra = {}) => out.push({ tag: 'circle', cx: at(cx), cy, r, fill, ...extra })
    const line = (x, y, w, opacity = 0.4) => rect(x, y, w, 4, accent, 2, { 'fill-opacity': opacity })
    const icon = (cx, cy, r, c) => {
        if (c.image) {
            out.push({ tag: 'image', href: c.image, x: at(cx) - r, y: cy - r, width: r * 2, height: r * 2, 'clip-path': `url(#c${uid}-round)` })
            return
        }
        circle(cx, cy, r, c.color)
        if (c.glyph) out.push({ tag: 'image', href: c.glyph, x: at(cx) - r * 0.58, y: cy - r * 0.58, width: r * 1.16, height: r * 1.16 })
        else out.push({ tag: 'circle', cx: at(cx), cy, r: r * 0.28, fill: '#fff' })
    }
    const panel = (x, y, w, h, rx = 8) => rect(x, y, w, h, '#fff', rx, { filter: `url(#c${uid}-shadow)` })

    switch (props.type) {
        case 'row':
            // Icons in a row beside the launcher.
            ch.forEach((c, i) => icon(83 - i * 29, L.cy, 10, c))
            break
        case 'card':
            // List: one card with a row per channel.
            panel(12, 12, 112, 83)
            line(20, 21, 50, 0.6)
            ch.forEach((c, i) => {
                const y = 41 + i * 19
                icon(27, y, 7, c)
                line(40, y - 4.5, 52)
                line(40, y + 1.5, 32, 0.2)
            })
            break
        case 'grid':
            // Grid: channel tiles side by side.
            panel(12, 12, 112, 83)
            line(20, 21, 50, 0.6)
            ch.forEach((c, i) => {
                const x = 20 + i * 33
                rect(x, 33, 29, 52, tint(c.color, '24'), 6)
                icon(x + 14.5, 53, 8, c)
                rect(x + 6, 70, 17, 4, accent, 2, { 'fill-opacity': 0.35 })
            })
            break
        case 'menu':
            // Menu: separate rows, no card around them.
            ch.forEach((c, i) => {
                const y = 82 - i * 25
                panel(28, y - 10, 96, 20, 6)
                icon(39, y, 6.5, c)
                line(51, y - 2, 52)
            })
            break
        case 'bubble': {
            // Bubble menu: a rounded bubble with tinted rows and a tail toward the launcher.
            panel(12, 12, 112, 83, 18)
            out.push({ tag: 'path', d: `M ${X(104)} 94 L ${X(116)} 94 L ${X(112)} 100 Z`, fill: '#fff' })
            ch.forEach((c, i) => {
                const y = 32 + i * 22
                rect(20, y - 9, 96, 18, tint(c.color, '26'), 9)
                icon(30, y, 6.5, c)
                line(42, y - 2, 46, 0.45)
            })
            break
        }
        case 'chat':
            // Chat window: colored header, then a row per channel.
            panel(12, 12, 112, 83)
            rect(12, 12, 112, 22, accent, 8)
            rect(12, 26, 112, 8, accent, 0)
            circle(24, 23, 6, '#fff', { 'fill-opacity': 0.35 })
            rect(35, 21, 44, 4, '#fff', 2, { 'fill-opacity': 0.85 })
            ch.forEach((c, i) => {
                const y = 47 + i * 17
                icon(24, y, 6.5, c)
                line(36, y - 2, 56)
            })
            break
        case 'corner':
            // Corner circle: the first channel sits beside the launcher, the next ones step up the arc.
            ch.forEach((c, i) => {
                const step = ch.length > 1 ? Math.min(45, 90 / (ch.length - 1)) : 0
                const a = (180 - i * step) * (Math.PI / 180)
                icon(L.cx + Math.cos(a) * 40, L.cy - Math.sin(a) * 40, 10, c)
            })
            break
        default:
            // Buttons: channel buttons stacked above the launcher.
            ch.forEach((c, i) => icon(L.cx, 80 - i * 29, 10, c))
    }

    // Launcher in the widget's corner, in the admin's color and shape. Every card shows the list
    // open, so the launcher shows × (close), as it does on the site and in the preview.
    const lx = X(L.cx)
    if (props.launcherShape === 'squircle') out.push({ tag: 'rect', x: lx - L.r, y: L.cy - L.r, width: L.r * 2, height: L.r * 2, rx: L.r * 0.8, fill: accent })
    else out.push({ tag: 'circle', cx: lx, cy: L.cy, r: L.r, fill: accent })
    out.push({ tag: 'path', d: `M ${lx - 4} ${L.cy - 4} l 8 8 M ${lx + 4} ${L.cy - 4} l -8 8`, stroke: '#fff', 'stroke-width': 2, 'stroke-linecap': 'round' })
    return out
})
</script>

<template>
    <svg :viewBox="`0 0 ${S} ${S}`" class="block w-full h-auto" style="pointer-events: none" aria-hidden="true">
        <defs>
            <linearGradient :id="`c${uid}-bg`" x1="3" y1="4" x2="131" y2="132.5" gradientUnits="userSpaceOnUse">
                <stop offset="0.19" :stop-color="accent" stop-opacity="0" />
                <stop offset="1" :stop-color="accent" stop-opacity="0.15" />
            </linearGradient>
            <filter :id="`c${uid}-shadow`" x="-10%" y="-10%" width="120%" height="130%">
                <feDropShadow dx="0" dy="2" stdDeviation="2" flood-color="#0F172A" flood-opacity=".12" />
            </filter>
            <clipPath :id="`c${uid}-round`" clipPathUnits="objectBoundingBox"><circle cx=".5" cy=".5" r=".5" /></clipPath>
        </defs>
        <rect width="136" height="136" fill="#fff" />
        <rect width="136" height="136" :fill="`url(#c${uid}-bg)`" />
        <component :is="s.tag" v-for="(s, i) in shapes" :key="i" v-bind="s" />
    </svg>
</template>
