<script setup>
import { computed, reactive, ref } from 'vue';
import { useWidgets } from '@store/widgets';
import { Text, InputLabel } from '@components';
import { useTranslation } from '../../composables/useTranslation';
import { CHANNELS, CHANNEL_COLORS } from '../../utility/channels';
import ChannelCard from './channels/ChannelCard.vue';
import WhatsAppSettings from './channels/WhatsAppSettings.vue';
import TelegramSettings from './channels/TelegramSettings.vue';
import ChannelTextFields from './channels/ChannelTextFields.vue';

const $widget = useWidgets();
const { t } = useTranslation();

const config = computed(() => $widget.currentWidget?.config || {})
const enabled = computed(() => config.value.channels?.enabled || [])

const channelNames = { whatsapp: 'WhatsApp', telegram: 'Telegram' }
const channelSubs = computed(() => ({ whatsapp: t('channel_sub_whatsapp'), telegram: t('channel_sub_telegram') }))
const glyph = channel => formychat_admin_vars.public + `images/${channel}-glyph.svg`
const settingsFor = { whatsapp: WhatsAppSettings, telegram: TelegramSettings }

const isEnabled = channel => enabled.value.includes(channel)

// Advanced options of each card stay folded until asked for.
const panels = reactive({})
const toggleChannel = (channel) => {
    const list = [...enabled.value]
    const index = list.indexOf(channel)

    if (index === -1) {
        list.push(channel)
    } else {
        // Settings of a removed channel are kept, so adding it back restores them.
        list.splice(index, 1)
    }

    config.value.channels.enabled = list
    $widget.errors.channels_enabled = false
}

const moveTo = (from, to) => {
    const list = [...enabled.value]
    if (to < 0 || to >= list.length || from === to) return
    const [channel] = list.splice(from, 1)
    list.splice(to, 0, channel)
    config.value.channels.enabled = list
}

// Drag to reorder: the grip is the drag source, so text in inputs can still be selected.
const drag = reactive({ from: null, over: null })
const onDragStart = (index, event) => {
    drag.from = index
    event.dataTransfer.effectAllowed = 'move'
    event.dataTransfer.setData('text/plain', enabled.value[index])
    // Show the whole card as the drag image, not just the grip.
    const card = event.target.closest('.formychat-channel-card')
    if (card) event.dataTransfer.setDragImage(card, 40, 30)
}
const onDrop = (index) => {
    if (drag.from !== null) moveTo(drag.from, index)
    drag.from = drag.over = null
}
const onDragEnd = () => { drag.from = drag.over = null }
</script>
<template>
    <div class="w-full h-full flex flex-col gap-8">
        <!-- Name  -->
        <div class="flex flex-col gap-2 max-w-md">
            <InputLabel semibold>{{ t('widget_name') }}</InputLabel>
            <Text v-model="$widget.currentWidget.name" :placeholder="t('widget_name')" />
        </div>

        <!-- Pick channels  -->
        <div class="flex flex-col gap-3">
            <div class="flex flex-col gap-1">
                <InputLabel semibold>{{ t('channels_title') }}</InputLabel>
                <p class="text-[13px] text-slate-500 m-0">{{ t('channels_hint') }}</p>
            </div>
            <div class="grid grid-cols-1 sm:grid-cols-2 gap-3 max-w-xl" name="channels_enabled" tabindex="-1">
                <button v-for="channel in CHANNELS" :key="channel" type="button"
                    class="group flex items-center gap-3 h-16 pl-3 pr-3.5 rounded-xl border text-left transition"
                    :class="isEnabled(channel) ? 'border-indigo-500 ring-1 ring-indigo-500 bg-indigo-50/40' : 'border-slate-200 bg-white hover:border-slate-300 hover:shadow-sm'"
                    :aria-pressed="isEnabled(channel) ? 'true' : 'false'" @click.prevent="toggleChannel(channel)">
                    <span class="w-10 h-10 rounded-full grid place-items-center shrink-0 transition"
                        :class="isEnabled(channel) ? '' : 'grayscale opacity-60 group-hover:grayscale-0 group-hover:opacity-100'"
                        :style="{ background: CHANNEL_COLORS[channel] }">
                        <img :src="glyph(channel)" class="w-5 h-5" alt="">
                    </span>
                    <span class="flex flex-col min-w-0">
                        <span class="text-sm font-semibold text-slate-900">{{ channelNames[channel] }}</span>
                        <span class="text-xs text-slate-500 truncate">{{ channelSubs[channel] }}</span>
                    </span>
                    <span class="ml-auto w-5 h-5 rounded-full grid place-items-center shrink-0 transition"
                        :class="isEnabled(channel) ? 'bg-indigo-600 text-white' : 'border border-slate-300 text-slate-400 group-hover:border-indigo-400 group-hover:text-indigo-500'">
                        <svg v-if="isEnabled(channel)" viewBox="0 0 24 24" class="w-3 h-3" fill="none" stroke="currentColor" stroke-width="3.5" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M20 6 9 17l-5-5" /></svg>
                        <svg v-else viewBox="0 0 24 24" class="w-3 h-3" fill="none" stroke="currentColor" stroke-width="3" stroke-linecap="round" aria-hidden="true"><path d="M12 5v14" /><path d="M5 12h14" /></svg>
                    </span>
                </button>
            </div>
            <transition name="fade">
                <div v-if="$widget.errors.channels_enabled" class="text-red-600 text-sm">{{ t('channels_required') }}</div>
            </transition>
        </div>

        <!-- Empty state  -->
        <div v-if="!enabled.length" class="rounded-2xl border border-dashed border-slate-300 bg-slate-50/50 px-6 py-10 text-center">
            <p class="m-0 text-sm text-slate-500">{{ t('channels_empty') }}</p>
        </div>

        <!-- One card per channel, in display order  -->
        <transition-group v-else tag="div" name="formychat-list" class="flex flex-col gap-4">
            <div v-for="(channel, index) in enabled" :key="channel"
                :class="{ 'opacity-50': drag.from === index }"
                @dragover.prevent="drag.from !== null && (drag.over = index)"
                @dragleave="drag.over === index && (drag.over = null)" @drop.prevent="onDrop(index)">
                <ChannelCard :channel="channel" :index="index" :total="enabled.length"
                    :open="!!panels[channel]" @update:open="panels[channel] = $event"
                    :drop-target="drag.from !== null && drag.over === index && drag.from !== index"
                    @dragstart="onDragStart(index, $event)" @dragend="onDragEnd"
                    @move="moveTo(index, index + $event)" @remove="toggleChannel(channel)">
                    <template #primary>
                        <component :is="settingsFor[channel]" section="primary" />
                    </template>
                    <template #toolbar>
                        <WhatsAppSettings v-if="channel === 'whatsapp'" section="toolbar" />
                    </template>
                    <template #advanced>
                        <!-- Name and description in the channel list; only a widget with several channels has one -->
                        <ChannelTextFields v-if="enabled.length > 1" :channel="channel" />
                        <component :is="settingsFor[channel]" section="advanced" />
                    </template>
                </ChannelCard>
            </div>
        </transition-group>
    </div>
</template>

<style scoped>
.formychat-list-move {
    transition: transform .3s ease;
}
</style>
