<script setup>
/**
 * Editor preview of the channel list styles drawn on the site by FormyChat Ultimate
 * (Icon row, Chat window, Tile grid, Menu, Bubble menu, Corner circle). Display only.
 * Sizes, colors and spacing mirror social-contact-form-ultimate/public/css/list-styles.css.
 * Placed inside the launcher's box, so it anchors to the launcher like on the site.
 *
 * @since 2.16.0
 */
import { computed, ref } from 'vue';
import { ChannelGlyph } from '@components';

const props = defineProps({
    type: { type: String, default: 'row' },
    left: { type: Boolean, default: false },
    open: { type: Boolean, default: true },
    accent: { type: String, default: '#4F46E5' },
    // Launcher size, e.g. "60px".
    size: { type: String, default: '60px' },
    title: { type: String, default: '' },
    // Line under the title (Chat window).
    message: { type: String, default: '' },
    // Chat window header; empty = launcher color.
    headerColor: { type: String, default: '' },
    showSub: { type: Boolean, default: true },
    // [{ key, label, sub, color, glyph, glyphColor, image }]: image = the channel's own uploaded icon, if any; glyphColor tints the glyph.
    channels: { type: Array, default: () => [] },
    // Channel being edited in the settings: drawn as hovered, with a dashed outline.
    highlight: { type: String, default: '' },
})
defineEmits(['close'])

const hovered = ref('')
const isOn = key => hovered.value === key || props.highlight === key
const ring = key => props.highlight === key ? { outline: '2px dashed #6366F1', outlineOffset: '3px' } : {}
const ease = 'cubic-bezier(.34, 1.56, .64, 1)'
const side = computed(() => props.left ? { left: 0 } : { right: 0 })

// The box: out of flow, above the launcher (beside it for the row).
const hostStyle = computed(() => {
    const base = {
        position: 'absolute',
        zIndex: 10,
        boxSizing: 'border-box',
        opacity: props.open ? 1 : 0,
        visibility: props.open ? 'visible' : 'hidden',
        pointerEvents: props.open ? 'auto' : 'none',
        transformOrigin: props.left ? 'bottom left' : 'bottom right',
        transition: 'opacity .22s ease, transform .22s ease',
    }
    if (props.type === 'corner') {
        // Fans out around the launcher itself.
        return { ...base, inset: 0, pointerEvents: 'none', transform: 'none' }
    }
    if (props.type === 'row') {
        const offset = `calc(${props.size} + 12px)`
        return {
            ...base,
            bottom: 0,
            height: props.size,
            ...(props.left ? { left: offset } : { right: offset }),
            transform: props.open ? 'none' : `translateX(${props.left ? '-10px' : '10px'})`,
        }
    }
    return {
        ...base,
        bottom: 'calc(100% + 14px)',
        ...side.value,
        transform: props.open ? 'none' : (props.type === 'bubble' ? 'translateY(10px) scale(.9)' : 'translateY(8px) scale(.97)'),
        transition: props.type === 'bubble' ? `opacity .2s ease, transform .3s ${ease}` : base.transition,
    }
})

const iconStyle = (channel, px) => ({
    position: 'relative', display: 'grid', placeItems: 'center', flex: 'none',
    width: px, height: px, borderRadius: '9999px', background: channel.image ? 'transparent' : channel.color,
})
const imageStyle = { width: '100%', height: '100%', borderRadius: '9999px', objectFit: 'cover' }

// Corner circle: the first channel sits beside the launcher (toward the screen centre),
// each next one steps 45 degrees up the arc (closer steps when there are many).
const cornerStyle = (i) => {
    const count = props.channels.length
    const step = count > 1 ? Math.min(Math.PI / 4, (Math.PI / 2) / (count - 1)) : 0
    const angle = Math.PI / 2 - i * step
    const radius = 1.45
    const dx = (props.left ? 1 : -1) * Math.sin(angle) * radius
    const dy = -Math.cos(angle) * radius
    const move = props.open ? `translate(calc(-50% + ${props.size} * ${dx.toFixed(3)}), calc(-50% + ${props.size} * ${dy.toFixed(3)}))` : 'translate(-50%, -50%) scale(.4)'
    return {
        position: 'absolute', left: '50%', top: '50%', display: 'grid', placeItems: 'center',
        pointerEvents: props.open ? 'auto' : 'none',
        opacity: props.open ? 1 : 0,
        transform: move,
        transition: `transform .35s ${ease} ${i * 50}ms, opacity .2s ease ${i * 50}ms`,
    }
}
const labelStyle = { fontSize: '15px', fontWeight: 600, lineHeight: 1.3, color: '#111827' }
const subStyle = { fontSize: '13px', lineHeight: 1.35, color: '#6B7280' }
const titleStyle = { flex: 1, minWidth: 0, fontSize: '15px', fontWeight: 700, lineHeight: 1.3, color: '#111827' }
const closeStyle = { flex: 'none', display: 'grid', placeItems: 'center', width: '28px', height: '28px', padding: 0, border: 0, borderRadius: '9999px', background: 'transparent', color: '#6B7280', cursor: 'pointer' }
const panelStyle = { maxWidth: 'calc(100vw - 32px)', background: '#fff', borderRadius: '16px', boxShadow: '0 18px 44px rgba(15, 23, 42, .2)', overflow: 'hidden' }
const arrowStyle = (key) => ({ flex: 'none', width: '14px', height: '14px', color: isOn(key) ? '#475569' : '#9CA3AF', transform: isOn(key) ? 'translateX(2px)' : 'none', transition: 'transform .15s ease, color .15s ease' })
const tint = (color, alpha) => color + alpha
</script>

<template>
    <div :style="hostStyle" :aria-hidden="open ? 'false' : 'true'" @click.stop>
        <!-- Icon row -->
        <div v-if="type === 'row'" :style="{ display: 'flex', flexDirection: left ? 'row' : 'row-reverse', alignItems: 'center', gap: '10px', height: '100%' }">
            <span v-for="(channel, i) in channels" :key="channel.key" :title="channel.label"
                :style="{ position: 'relative', display: 'grid', placeItems: 'center', opacity: open ? 1 : 0, transform: open ? 'none' : 'scale(.6)', transition: `transform .3s ${ease} ${i * 50}ms, opacity .2s ease ${i * 50}ms` }"
                @mouseenter="hovered = channel.key" @mouseleave="hovered = ''">
                <span :style="{ ...iconStyle(channel, `calc(${size} * .8)`), boxShadow: '0 6px 18px rgba(15, 23, 42, .2)', transform: isOn(channel.key) ? 'scale(1.08)' : 'none', transition: 'transform .2s ease', ...ring(channel.key) }">
                    <img v-if="channel.image" :src="channel.image" :style="imageStyle" alt=""><ChannelGlyph v-else :channel="channel.key" :src="channel.glyph" :color="channel.glyphColor" size="55%" />
                </span>
                <span v-if="channel.showLabel !== false" :style="{ position: 'absolute', bottom: 'calc(100% + 8px)', left: '50%', padding: '5px 10px', borderRadius: '8px', background: '#111827', color: '#fff', fontSize: '12px', fontWeight: 600, lineHeight: 1.2, whiteSpace: 'nowrap', pointerEvents: 'none', opacity: isOn(channel.key) ? 1 : 0, transform: isOn(channel.key) ? 'translate(-50%, 0)' : 'translate(-50%, 4px)', transition: 'opacity .15s ease, transform .15s ease' }">{{ channel.label }}</span>
            </span>
        </div>

        <!-- Chat window -->
        <div v-else-if="type === 'chat'" :style="{ ...panelStyle, width: '320px' }">
            <div :style="{ display: 'flex', alignItems: 'center', gap: '10px', padding: '16px 12px 16px 16px', background: headerColor || accent }">
                <span :style="{ flex: 'none', display: 'grid', placeItems: 'center', width: '38px', height: '38px', borderRadius: '9999px', background: 'rgba(255, 255, 255, .2)', color: '#fff' }">
                    <svg viewBox="0 0 24 24" fill="currentColor" style="width: 20px; height: 20px" aria-hidden="true"><path d="M4 5.5A2.5 2.5 0 0 1 6.5 3h11A2.5 2.5 0 0 1 20 5.5v8a2.5 2.5 0 0 1-2.5 2.5H10l-4.5 4v-4h0A1.5 1.5 0 0 1 4 14.5z" /></svg>
                </span>
                <div :style="{ ...titleStyle, color: '#fff' }">
                    <div>{{ title }}</div>
                    <div v-if="message" :style="{ marginTop: '2px', fontSize: '13px', fontWeight: 400, lineHeight: 1.35, color: 'rgba(255, 255, 255, .85)' }">{{ message }}</div>
                </div>
                <button type="button" :style="{ ...closeStyle, color: '#fff' }" @click.stop="$emit('close')">
                    <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" style="width: 16px; height: 16px" aria-hidden="true"><path d="M6 6l12 12M18 6 6 18" /></svg>
                </button>
            </div>
            <div :style="{ display: 'flex', flexDirection: 'column', gap: '8px', padding: '12px', background: '#F8FAFC' }">
                <div v-for="channel in channels" :key="channel.key"
                    :style="{ display: 'flex', alignItems: 'center', gap: '12px', padding: '10px 12px', border: '1px solid', borderColor: isOn(channel.key) ? '#E2E8F0' : '#EEF2F7', borderRadius: '12px', background: '#fff', boxShadow: isOn(channel.key) ? '0 4px 14px rgba(15, 23, 42, .08)' : 'none', transition: 'border-color .15s ease, box-shadow .15s ease', cursor: 'pointer', ...ring(channel.key) }"
                    @mouseenter="hovered = channel.key" @mouseleave="hovered = ''">
                    <span :style="iconStyle(channel, '40px')">
                        <img v-if="channel.image" :src="channel.image" :style="imageStyle" alt=""><ChannelGlyph v-else :channel="channel.key" :src="channel.glyph" :color="channel.glyphColor" size="55%" />
                        <span :style="{ position: 'absolute', right: 0, bottom: 0, width: '11px', height: '11px', borderRadius: '9999px', background: '#22C55E', boxShadow: '0 0 0 2px #fff' }"></span>
                    </span>
                    <span :style="{ display: 'flex', flexDirection: 'column', flex: 1, minWidth: 0 }">
                        <span :style="labelStyle">{{ channel.label }}</span>
                        <span v-if="showSub && channel.sub" :style="subStyle">{{ channel.sub }}</span>
                    </span>
                    <svg viewBox="0 0 16 16" fill="currentColor" :style="arrowStyle(channel.key)" aria-hidden="true"><path d="M4.646 1.646a.5.5 0 0 1 .708 0l6 6a.5.5 0 0 1 0 .708l-6 6a.5.5 0 0 1-.708-.708L10.293 8 4.646 2.354a.5.5 0 0 1 0-.708" /></svg>
                </div>
            </div>
        </div>

        <!-- Tile grid -->
        <div v-else-if="type === 'grid'" :style="{ ...panelStyle, width: '300px', padding: '14px' }">
            <div :style="{ display: 'flex', alignItems: 'center', gap: '10px', marginBottom: '12px', paddingLeft: '2px' }">
                <div :style="titleStyle">{{ title }}</div>
                <button type="button" :style="closeStyle" @click.stop="$emit('close')">
                    <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" style="width: 16px; height: 16px" aria-hidden="true"><path d="M6 6l12 12M18 6 6 18" /></svg>
                </button>
            </div>
            <div :style="{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: '10px' }">
                <div v-for="(channel, i) in channels" :key="channel.key"
                    :style="{ display: 'flex', flexDirection: 'column', alignItems: 'center', justifyContent: 'center', gap: '8px', minHeight: '96px', padding: '14px 8px', border: '1px solid', borderColor: isOn(channel.key) ? channel.color : 'transparent', borderRadius: '14px', background: tint(channel.color, isOn(channel.key) ? '24' : '14'), textAlign: 'center', transform: isOn(channel.key) ? 'translateY(-2px)' : 'none', transition: 'transform .15s ease, border-color .15s ease, background .15s ease', cursor: 'pointer', gridColumn: channels.length % 2 === 1 && i === channels.length - 1 ? '1 / -1' : 'auto', ...ring(channel.key) }"
                    @mouseenter="hovered = channel.key" @mouseleave="hovered = ''">
                    <span :style="{ ...iconStyle(channel, '46px'), boxShadow: '0 6px 16px rgba(15, 23, 42, .14)' }">
                        <img v-if="channel.image" :src="channel.image" :style="imageStyle" alt=""><ChannelGlyph v-else :channel="channel.key" :src="channel.glyph" :color="channel.glyphColor" size="55%" />
                    </span>
                    <span :style="{ ...labelStyle, fontSize: '14px', maxWidth: '100%', overflow: 'hidden', textOverflow: 'ellipsis', whiteSpace: 'nowrap' }">{{ channel.label }}</span>
                </div>
            </div>
        </div>

        <!-- Menu: plain white rows, icon and name, no card and no title -->
        <div v-else-if="type === 'menu'" :style="{ display: 'flex', flexDirection: 'column', alignItems: left ? 'flex-start' : 'flex-end', gap: '8px', width: '220px' }">
            <div v-for="(channel, i) in channels" :key="channel.key"
                :style="{ display: 'flex', alignItems: 'center', gap: '10px', width: '100%', padding: '8px 12px 8px 8px', borderRadius: '10px', background: '#fff', boxShadow: isOn(channel.key) ? '0 8px 20px rgba(15, 23, 42, .16)' : '0 4px 14px rgba(15, 23, 42, .12)', transform: isOn(channel.key) ? 'translateY(-1px)' : 'none', transition: 'box-shadow .15s ease, transform .15s ease', cursor: 'pointer', ...ring(channel.key) }"
                @mouseenter="hovered = channel.key" @mouseleave="hovered = ''">
                <span :style="iconStyle(channel, '32px')">
                    <img v-if="channel.image" :src="channel.image" :style="imageStyle" alt=""><ChannelGlyph v-else :channel="channel.key" :src="channel.glyph" :color="channel.glyphColor" size="55%" />
                </span>
                <span :style="{ ...labelStyle, fontSize: '14px', flex: 1, minWidth: 0, overflow: 'hidden', textOverflow: 'ellipsis', whiteSpace: 'nowrap' }">{{ channel.label }}</span>
            </div>
        </div>

        <!-- Corner circle: icons fanned around the launcher -->
        <template v-else-if="type === 'corner'">
            <span v-for="(channel, i) in channels" :key="channel.key" :title="channel.label" :style="cornerStyle(i)"
                @mouseenter="hovered = channel.key" @mouseleave="hovered = ''">
                <span :style="{ ...iconStyle(channel, `calc(${size} * .72)`), boxShadow: '0 6px 18px rgba(15, 23, 42, .2)', transform: isOn(channel.key) ? 'scale(1.08)' : 'none', transition: 'transform .2s ease', ...ring(channel.key) }">
                    <img v-if="channel.image" :src="channel.image" :style="imageStyle" alt=""><ChannelGlyph v-else :channel="channel.key" :src="channel.glyph" :color="channel.glyphColor" size="55%" />
                </span>
                <span v-if="channel.showLabel !== false" :style="{ position: 'absolute', bottom: 'calc(100% + 8px)', left: '50%', padding: '5px 10px', borderRadius: '8px', background: '#111827', color: '#fff', fontSize: '12px', fontWeight: 600, lineHeight: 1.2, whiteSpace: 'nowrap', pointerEvents: 'none', opacity: isOn(channel.key) ? 1 : 0, transform: isOn(channel.key) ? 'translate(-50%, 0)' : 'translate(-50%, 4px)', transition: 'opacity .15s ease, transform .15s ease' }">{{ channel.label }}</span>
            </span>
        </template>

        <!-- Bubble menu -->
        <div v-else-if="type === 'bubble'"
            :style="{ position: 'relative', display: 'flex', flexDirection: 'column', gap: '6px', width: '260px', padding: '10px', background: '#fff', borderRadius: '22px', boxShadow: '0 16px 40px rgba(15, 23, 42, .18)' }">
            <div v-if="title" :style="{ padding: '4px 8px 2px', fontSize: '13px', fontWeight: 600, lineHeight: 1.3, color: '#6B7280' }">{{ title }}</div>
            <div v-for="channel in channels" :key="channel.key"
                :style="{ position: 'relative', zIndex: 1, display: 'flex', alignItems: 'center', gap: '10px', padding: '6px 14px 6px 6px', borderRadius: '9999px', background: tint(channel.color, isOn(channel.key) ? '2E' : '1A'), transition: 'background .15s ease', cursor: 'pointer', ...ring(channel.key) }"
                @mouseenter="hovered = channel.key" @mouseleave="hovered = ''">
                <span :style="iconStyle(channel, '36px')">
                    <img v-if="channel.image" :src="channel.image" :style="imageStyle" alt=""><ChannelGlyph v-else :channel="channel.key" :src="channel.glyph" :color="channel.glyphColor" size="55%" />
                </span>
                <span :style="{ display: 'flex', flexDirection: 'column', flex: 1, minWidth: 0 }">
                    <span :style="{ ...labelStyle, fontSize: '14px' }">{{ channel.label }}</span>
                    <span v-if="showSub && channel.sub" :style="{ ...subStyle, fontSize: '12px' }">{{ channel.sub }}</span>
                </span>
            </div>
            <!-- Tail toward the launcher -->
            <span :style="{ position: 'absolute', bottom: '-7px', [left ? 'left' : 'right']: `calc(${size} / 2 - 8px)`, width: '16px', height: '16px', background: '#fff', borderRadius: '0 0 4px 0', transform: 'rotate(45deg)', boxShadow: '4px 4px 8px rgba(15, 23, 42, .06)' }"></span>
        </div>
    </div>
</template>
