<script setup>
import { computed, onMounted, watch } from 'vue';
import { useWidgets } from '@store/widgets';
import { Select, Text, IconUploader, Toggle, InputGroup, InputLabel } from '@components';
import { useTranslation } from '../../../composables/useTranslation';
import ChannelIconField from './ChannelIconField.vue';
import { buildWhatsappUrl } from '../../../utility/channels';

const props = defineProps({
    // 'primary': number / group / agents. 'toolbar': the Agents switch. 'advanced': the card's Settings panel.
    section: { type: String, default: 'primary' },
})

const $widget = useWidgets();
const { t } = useTranslation();
const whatsapp = computed(() => $widget.currentWidget?.config?.whatsapp || {})
const isLocked = !window.formychat_admin_vars.is_premium || false

const destinations = computed(() => ({ phone: t('tab_number'), group: t('tab_group') }))
const agentActions = computed(() => ({ show_form: t('load_selected_form'), redirect: t('redirect_whatsapp_directly') }))
const numberError = computed(() => !$widget.isValidPhone(whatsapp.value.number) || !!$widget.errors.whatsapp_number)

const testUrl = computed(() => {
    const number = String(whatsapp.value.country_code || '') + String(whatsapp.value.number || '')
    return /^\d{7,}$/.test(number) ? buildWhatsappUrl(number, t('test_message')) : ''
})

// Locked choices stay put; the click still reaches the upgrade prompt through .formychat-locked.
const setDestination = (dest) => {
    if (isLocked && dest === 'group') return
    whatsapp.value.destination_type = dest
}

const setAgentAction = (action) => {
    if (isLocked && action === 'redirect') return
    whatsapp.value.on_click_agent = action
}

// Use modal store.
import { useModal } from '@store/modal'
const $modal = useModal();

const resetWhatsAppError = () => {
    $widget.errors.whatsapp_number = false;
}

// Agent 
const addAgent = () => {
    whatsapp.value.agents = whatsapp.value.agents || [];
    whatsapp.value.agents.push({ 
        name: t('agent_default_name', { number: whatsapp.value.agents.length + 1 }), 
        subtitle: '', 
        number: '', 
        country_code: String(window.formychat_country_code || '44') });
    $widget.errors.whatsapp_agents = false;
}

const toggleAgents = () => {
    if (isLocked) return
    whatsapp.value.agent_mode = whatsapp.value.agent_mode === 'agents' ? 'single' : 'agents'
    if (whatsapp.value.agent_mode === 'agents' && !(whatsapp.value.agents || []).length) {
        addAgent()
    }
}

const deleteAgent = async (index) => {
    // Use modal to confirm deletion
    const confirmDelete = await $modal.prompt({
        title: t('delete_agent'),
        message: t('confirm_delete_agent'),
    });

    if (confirmDelete.ok) {
        whatsapp.value.agents.splice(index, 1);
    }
}

const moveAgent = (index, direction) => {
    const agents = whatsapp.value.agents;
    const newIndex = direction === 'up' ? index - 1 : index + 1;

    if (newIndex < 0 || newIndex >= agents.length) {
        return;
    }

    const agent = agents[index];
    agents.splice(index, 1);
    agents.splice(newIndex, 0, agent);
}


/**
 * Apply the geolocated dial code, but only while the field is still empty.
 *
 * Awaits the resolver rather than listening for `formychat_ip_loaded`, because
 * that event can fire before this component mounts and would then be missed.
 *
 * `whatsapp` is a computed that yields `{}` until the widget is loaded, so the
 * write is guarded on the real config object being present; otherwise it would
 * land on a throwaway object and be lost.
 */
const applyCountryCode = async () => {
    const config = $widget.currentWidget?.config?.whatsapp;

    if (!config || config.country_code) {
        return;
    }

    const detected = await window.formychat_country_code_ready;

    // Re-resolve after awaiting: the widget may have been swapped, or a code
    // may have arrived, while the lookup was in flight.
    const current = $widget.currentWidget?.config?.whatsapp;

    if (!current || current.country_code) {
        return;
    }

    $widget.setCountryCode(String(detected || '44'));
}

// The widget can load after this component mounts (and can be swapped while it
// stays mounted), so react to it becoming available rather than reading once.
watch(
    () => $widget.currentWidget?.config?.whatsapp?.country_code,
    (value) => {
        if (!value) {
            applyCountryCode();
        }
    },
    { immediate: true }
);
// on onMounted.
onMounted(async () => {
    // Set default agent mode
    whatsapp.value.agent_mode = whatsapp.value.agent_mode || 'single';
    whatsapp.value.destination_type = whatsapp.value.destination_type || 'phone';

    applyCountryCode();

});
</script>
<template>
    <!-- Toolbar: switch between one number and several agents  -->
    <button v-if="props.section === 'toolbar'" type="button"
        class="inline-flex items-center gap-1.5 h-8 px-3 rounded-lg border text-[13px] font-medium transition"
        :class="[whatsapp.agent_mode === 'agents' ? 'border-indigo-200 bg-indigo-50 text-indigo-700' : 'border-slate-200 bg-white text-slate-600 hover:border-slate-300 hover:text-slate-800', isLocked ? 'formychat-locked' : '']"
        :aria-pressed="whatsapp.agent_mode === 'agents' ? 'true' : 'false'" @click="toggleAgents">
        <svg viewBox="0 0 24 24" class="w-4 h-4" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">
            <path d="M16 21v-2a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v2" /><circle cx="9" cy="7" r="4" /><path d="M22 21v-2a4 4 0 0 0-3-3.87" /><path d="M16 3.13a4 4 0 0 1 0 7.75" />
        </svg>
        {{ t('agents_button') }}
        <svg v-if="isLocked" viewBox="0 0 24 24" class="w-3.5 h-3.5 text-amber-500" fill="none" stroke="currentColor" stroke-width="2.25" stroke-linecap="round" stroke-linejoin="round" aria-label="Ultimate"><rect x="4" y="11" width="16" height="10" rx="2" /><path d="M8 11V7a4 4 0 0 1 8 0v4" /></svg>
    </button>

    <!-- Primary: number, group or agents  -->
    <div v-else-if="props.section === 'primary'" class="flex flex-col gap-2.5 max-w-xl">
        <template v-if="whatsapp.agent_mode !== 'agents'">
            <div class="inline-flex w-fit rounded-lg bg-slate-100 p-0.5" role="tablist" :aria-label="t('whatsapp_destination')">
                <button v-for="(label, dest) in destinations" :key="dest" type="button" role="tab"
                    class="h-7 px-3 rounded-md text-[13px] font-medium transition inline-flex items-center gap-1.5"
                    :class="[whatsapp.destination_type === dest ? 'bg-white text-slate-900 shadow-sm' : 'text-slate-500 hover:text-slate-700', isLocked && dest === 'group' ? 'formychat-locked' : '']"
                    :aria-selected="whatsapp.destination_type === dest ? 'true' : 'false'" @click="setDestination(dest)">
                    {{ label }}
                    <svg v-if="isLocked && dest === 'group'" viewBox="0 0 24 24" class="w-3.5 h-3.5 text-amber-500" fill="none" stroke="currentColor" stroke-width="2.25" stroke-linecap="round" stroke-linejoin="round" aria-label="Ultimate"><rect x="4" y="11" width="16" height="10" rx="2" /><path d="M8 11V7a4 4 0 0 1 8 0v4" /></svg>
                </button>
            </div>

            <!-- Phone number  -->
            <template v-if="whatsapp.destination_type !== 'group'">
                <div class="formychat-wa-phone-row flex items-center gap-2">
                    <Select :options="$widget.contents.countries" v-model="whatsapp.country_code" :cursor="false"
                        class="w-24 shrink-0" size="w-24" :placeholder="t('select')" white teleport
                        :error="$widget.errors.whatsapp_country_code"
                        @select="$widget.errors.whatsapp_country_code = false"
                        dropdown-anchor-selector=".formychat-wa-phone-row" :dropdown-min-width="360" :excerpt="120" />
                    <div class="flex-1 min-w-0 flex items-center h-11 rounded-xl border bg-white transition focus-within:ring-4"
                        :class="numberError ? 'border-red-400 focus-within:ring-red-500/10' : 'border-slate-200 hover:border-slate-300 focus-within:border-indigo-500 focus-within:ring-indigo-500/10'">
                        <input name="whatsapp_number" v-model="whatsapp.number" type="tel" autocomplete="off"
                            class="formychat-bare-input min-w-0 !px-3.5" :aria-invalid="numberError ? 'true' : 'false'"
                            :placeholder="t('whatsapp_number_placeholder')" @keydown="resetWhatsAppError">
                        <a :href="testUrl || undefined" target="_blank" rel="noopener noreferrer" :title="testUrl ? t('test_link_hint') : ''"
                            class="formychat-test-btn mr-1.5" :class="{ 'is-disabled': !testUrl }" :aria-disabled="testUrl ? 'false' : 'true'">
                            {{ t('test_short') }}
                            <svg viewBox="0 0 24 24" class="w-3.5 h-3.5" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M7 17 17 7" /><path d="M7 7h10v10" /></svg>
                        </a>
                    </div>
                </div>
                <span class="text-xs text-slate-500">{{ t('whatsapp_number_input_hint') }}</span>
            </template>

            <!-- Group invite link  -->
            <template v-else>
                <div class="flex items-center h-11 rounded-xl border bg-white transition focus-within:ring-4"
                    :class="$widget.errors.group_invite_code ? 'border-red-400 focus-within:ring-red-500/10' : 'border-slate-200 hover:border-slate-300 focus-within:border-indigo-500 focus-within:ring-indigo-500/10'">
                    <input name="group_invite_code" v-model="whatsapp.group_invite_code" type="text" autocomplete="off"
                        class="formychat-bare-input min-w-0 !px-3.5"
                        :placeholder="t('whatsapp_group_invite_placeholder')" @keydown="$widget.errors.group_invite_code = false">
                </div>
                <span class="text-xs text-slate-500">{{ t('whatsapp_group_invite_hint') }}</span>
            </template>
        </template>

        <!-- Agents  -->
        <template v-else>
            <div v-for="(agent, index) in (whatsapp.agents || [])" :key="index"
                class="relative rounded-xl border border-slate-200 bg-slate-50/60 p-4 flex flex-col gap-3">
                <div class="absolute right-2 top-2 flex items-center gap-0.5">
                    <button type="button" :disabled="index === 0" class="w-7 h-7 grid place-items-center rounded-md text-slate-400 hover:text-slate-700 hover:bg-white disabled:opacity-30 disabled:pointer-events-none"
                        :title="t('move_up')" :aria-label="t('move_up')" @click="moveAgent(index, 'up')">
                        <svg viewBox="0 0 24 24" class="w-4 h-4" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="m18 15-6-6-6 6" /></svg>
                    </button>
                    <button type="button" :disabled="index === whatsapp.agents.length - 1" class="w-7 h-7 grid place-items-center rounded-md text-slate-400 hover:text-slate-700 hover:bg-white disabled:opacity-30 disabled:pointer-events-none"
                        :title="t('move_down')" :aria-label="t('move_down')" @click="moveAgent(index, 'down')">
                        <svg viewBox="0 0 24 24" class="w-4 h-4" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="m6 9 6 6 6-6" /></svg>
                    </button>
                    <button type="button" class="w-7 h-7 grid place-items-center rounded-md text-slate-400 hover:text-red-600 hover:bg-red-50"
                        :title="t('delete_agent')" :aria-label="t('delete_agent')" @click="deleteAgent(index)">
                        <svg viewBox="0 0 24 24" class="w-4 h-4" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M3 6h18" /><path d="M19 6v14a2 2 0 0 1-2 2H7a2 2 0 0 1-2-2V6" /><path d="M8 6V4a2 2 0 0 1 2-2h4a2 2 0 0 1 2 2v2" /></svg>
                    </button>
                </div>
                <div class="pr-24">
                    <IconUploader v-model="agent.avatar" v-model:custom="agent.custom_avatar" :default="Image('whatsapp-circle.svg')" />
                </div>
                <div class="grid grid-cols-1 sm:grid-cols-2 gap-3">
                    <InputGroup>
                        <InputLabel>{{ t('agent_name') }}</InputLabel>
                        <Text :placeholder="t('agent_name_example')" v-model="agent.name" white />
                    </InputGroup>
                    <InputGroup>
                        <InputLabel>{{ t('subtitle_designation') }}</InputLabel>
                        <Text :placeholder="t('subtitle_example')" v-model="agent.subtitle" white />
                    </InputGroup>
                </div>
                <InputGroup>
                    <InputLabel>{{ t('agent_whatsapp_number') }}</InputLabel>
                    <div class="formychat-wa-phone-row flex items-center gap-2">
                        <Select :options="$widget.contents.countries" v-model="agent.country_code" :cursor="false"
                            class="w-24 shrink-0" size="w-24" white teleport
                            :error="$widget.errors['agent_country_code_' + index]"
                            @select="$widget.errors['agent_country_code_' + index] = false"
                            :placeholder="t('select')" dropdown-anchor-selector=".formychat-wa-phone-row"
                            :dropdown-min-width="360" :excerpt="120" />
                        <Text v-model="agent.number" type="text" white :name="'agent_number_' + index"
                            @keydown="$widget.errors['agent_number_' + index] = false"
                            :error="!$widget.isValidPhone(agent.number) || $widget.errors['agent_number_' + index]"
                            :placeholder="t('whatsapp_number_placeholder')" />
                    </div>
                </InputGroup>
            </div>

            <transition name="fade">
                <div v-if="$widget.errors.whatsapp_agents" class="text-sm text-red-600 bg-red-50 border border-red-200 rounded-lg px-3 py-2">{{ t('add_one_agent_error') }}</div>
            </transition>

            <button type="button" class="inline-flex w-fit items-center gap-1.5 h-9 px-3 rounded-lg border border-dashed border-slate-300 text-[13px] font-medium text-slate-600 hover:border-indigo-400 hover:text-indigo-600 hover:bg-indigo-50/40 transition" @click="addAgent">
                <svg viewBox="0 0 24 24" class="w-4 h-4" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" aria-hidden="true"><path d="M12 5v14" /><path d="M5 12h14" /></svg>
                {{ t('add_new_agent') }}
            </button>
        </template>
    </div>

    <!-- Advanced: inside the Settings panel  -->
    <template v-else>
        <!-- Channel icon and color (2.16.0), first: it is what visitors see  -->
        <ChannelIconField channel="whatsapp" />

        <div class="flex flex-col gap-4">
            <h4 class="m-0 text-[13px] font-semibold text-slate-900">{{ t('behaviors') }}</h4>
            <Toggle v-model="whatsapp.redirect_after_submit" locked :hints="t('after_submit_hint_whatsapp')">{{ t('after_submit_redirect_whatsapp') }}</Toggle>
            <Toggle v-model="whatsapp.new_tab" :hints="t('open_whatsapp_new_tab_hint')">{{ t('open_whatsapp_new_tab') }}</Toggle>
            <Toggle v-model="whatsapp.web_version" locked :hints="t('whatsapp_web_version_hint')">{{ t('whatsapp_web_version') }}</Toggle>
        </div>

        <div v-if="whatsapp.agent_mode === 'agents'" class="flex flex-col gap-2.5">
            <h4 class="m-0 text-[13px] font-semibold text-slate-900">{{ t('on_click_agent') }}</h4>
            <div class="inline-flex flex-wrap w-fit rounded-lg bg-slate-100 p-0.5">
                <button v-for="(label, action) in agentActions" :key="action" type="button"
                    class="h-8 px-3 rounded-md text-[13px] font-medium transition inline-flex items-center gap-1.5"
                    :class="[whatsapp.on_click_agent === action ? 'bg-white text-slate-900 shadow-sm' : 'text-slate-500 hover:text-slate-700', isLocked && action === 'redirect' ? 'formychat-locked' : '']"
                    :aria-pressed="whatsapp.on_click_agent === action ? 'true' : 'false'" @click="setAgentAction(action)">
                    {{ label }}
                    <svg v-if="isLocked && action === 'redirect'" viewBox="0 0 24 24" class="w-3.5 h-3.5 text-amber-500" fill="none" stroke="currentColor" stroke-width="2.25" stroke-linecap="round" stroke-linejoin="round" aria-label="Ultimate"><rect x="4" y="11" width="16" height="10" rx="2" /><path d="M8 11V7a4 4 0 0 1 8 0v4" /></svg>
                </button>
            </div>
        </div>
    </template>
</template>
