<script setup>
import { ref, computed, onMounted } from 'vue';
import { useWidgets } from '@store/widgets';
import { useRoute, useRouter } from 'vue-router';
import { Group, Tabs, InputLabel, InputGroup, IconUploader, Text, Button, Select, Toggle, Tooltip, Textarea, ColorPicker, ProBadge, LockedHover } from '@components';
import { useTranslation } from '../../composables/useTranslation';

const { t } = useTranslation();

const $widget = useWidgets();
const greetings = computed( () => $widget.currentWidget.config?.greetings || {});

const simple = computed( () => $widget.currentWidget.config?.greetings?.templates?.simple || {});
const wave = computed( () => $widget.currentWidget.config?.greetings?.templates?.wave || {});

const sizes = computed(() => ({ 
    small: t('small'), 
    medium: t('medium'), 
    large: t('large'), 
    custom: t('custom') 
}));

const isLocked = computed ( () => !formychat_admin_vars.is_premium )

const templateLabel = (template) => {
    const labels = { simple: t('greeting_template_simple'), wave: t('greeting_template_wave'), whatsapp: t('greeting_template_whatsapp') };
    return labels[template] || template;
}


// Wave and Style 2 are FormyChat Ultimate; WhatsApp is upcoming.
const templateLocked = template => template === 'whatsapp' || (template === 'wave' && isLocked.value)
const styleLocked = styleId => styleId === 2 && isLocked.value

// Card frame, as in Widget style: selected = indigo, else slate with a hover lift. Locked cards look
// the same; the Ultimate pill shows on hover.
const cardFrame = (selected) => selected
    ? 'border-indigo-500 ring-1 ring-indigo-500 bg-white'
    : 'border-slate-200 bg-white group-hover:border-slate-300 group-hover:shadow-sm'

// Locked: the click reaches the upgrade prompt through .formychat-locked.
const setTemplate = (template) => {
    if ( templateLocked(template) ) return;

    greetings.value.template = template;
}

const setStyle = ( styleId ) => {

    if ( styleLocked(styleId) ) return;

    greetings.value.style = styleId;

    if ( greetings.value.template === 'wave' ) {
        wave.value.icon_position = styleId === 1 ? 'before_heading' : 'before_cta';
    } 
}

// With several channels the greeting opens the channel list instead of the form.
const greetingActions = computed(() => {
    const many = ($widget.currentWidget?.config?.channels?.enabled || []).length > 1
    if (!many) {
        return { show_form: t('load_selected_form'), redirect: t('redirect_whatsapp_directly') }
    }
    return {
        list: t('greeting_open_channel_list'),
        show_form: t('greeting_open_first_form'),
        redirect: t('greeting_redirect_first_channel'),
    }
})
</script>
<template>
    <div class="w-full h-full space-y-6">
        <InputGroup>
            <Toggle v-model="greetings.enabled" :label="t('enable_greetings')">{{ t('display_greeting_popup') }} </Toggle>
        </InputGroup>

        <InputGroup class="w-full h-full space-y-6" :condition="greetings.enabled == true">

            <InputGroup>
                <InputLabel>{{ t('choose_greetings_template') }}</InputLabel>

                <!-- Same cards as Widget style: frame, then radio and name. Locked: grey frame, Ultimate pill on hover. -->
                <div class="flex flex-wrap gap-4" role="radiogroup" :aria-label="t('choose_greetings_template')">
                    <LockedHover v-for="template in ['simple', 'wave', 'whatsapp']" :key="template"
                        :locked="templateLocked(template)" :upgrade="template !== 'whatsapp'" :text="template === 'whatsapp' ? t('upcoming') : ''"
                        role="radio" tabindex="0" :aria-checked="greetings.template == template ? 'true' : 'false'" :aria-label="templateLabel(template)"
                        style="--formychat-lh-y: -11px"
                        class="group w-40 flex flex-col gap-1.5 rounded-lg focus:outline-none focus-visible:ring-2 focus-visible:ring-indigo-500 focus-visible:ring-offset-2"
                        :class="template === 'whatsapp' ? 'cursor-not-allowed' : 'cursor-pointer'"
                        @click.prevent="setTemplate(template)" @keydown.enter.prevent="setTemplate(template)" @keydown.space.prevent="setTemplate(template)">
                        <span class="h-40 rounded-xl border overflow-hidden flex items-center justify-center transition"
                            :class="cardFrame(greetings.template == template)">
                            <img class="w-1/2" :src="Image(`greetings/styles/${template}${template === 'whatsapp' ? '' : '-1'}.png`)" alt="">
                        </span>
                        <span class="flex items-start gap-1.5">
                            <span class="mt-px w-3.5 h-3.5 rounded-full border grid place-items-center shrink-0 transition"
                                :class="greetings.template == template ? 'border-indigo-600' : 'border-slate-300 group-hover:border-slate-400'">
                                <span v-if="greetings.template == template" class="w-1.5 h-1.5 rounded-full bg-indigo-600"></span>
                            </span>
                            <span class="text-xs leading-tight" :class="greetings.template == template ? 'font-semibold text-slate-900' : 'font-medium text-slate-600'">{{ templateLabel(template) }}</span>
                        </span>
                    </LockedHover>
                </div>
            </InputGroup>

            <InputGroup>
                <div class="flex flex-wrap gap-4" role="radiogroup" :aria-label="t('choose_greetings_template')">
                    <LockedHover v-for="styleId in [1, 2]" :key="styleId" :locked="styleLocked(styleId)"
                        role="radio" tabindex="0" :aria-checked="greetings.style == styleId ? 'true' : 'false'" :aria-label="t('style_number', { number: styleId })"
                        style="--formychat-lh-y: -11px"
                        class="group w-24 flex flex-col gap-1.5 cursor-pointer rounded-lg focus:outline-none focus-visible:ring-2 focus-visible:ring-indigo-500 focus-visible:ring-offset-2"
                        @click.prevent="setStyle(styleId)" @keydown.enter.prevent="setStyle(styleId)" @keydown.space.prevent="setStyle(styleId)">
                        <span class="h-24 rounded-xl border overflow-hidden flex items-center justify-center transition"
                            :class="cardFrame(greetings.style == styleId)">
                            <img class="w-2/3 h-auto" :src="Image(`greetings/styles/${greetings.template}-${styleId}.png`)" alt="">
                        </span>
                        <span class="flex items-start gap-1.5">
                            <span class="mt-px w-3.5 h-3.5 rounded-full border grid place-items-center shrink-0 transition"
                                :class="greetings.style == styleId ? 'border-indigo-600' : 'border-slate-300 group-hover:border-slate-400'">
                                <span v-if="greetings.style == styleId" class="w-1.5 h-1.5 rounded-full bg-indigo-600"></span>
                            </span>
                            <span class="text-xs leading-tight" :class="greetings.style == styleId ? 'font-semibold text-slate-900' : 'font-medium text-slate-600'">{{ t('style_number', { number: styleId }) }}</span>
                        </span>
                    </LockedHover>
                </div>
            </InputGroup>

            <Group :title="t('customize_greetings')" :gap="false">

                <!-- Simple  -->
                <div class="space-y-6" v-if="greetings.template === 'simple'">
                    <div class="bg-slate-50 p-5 space-y-5 rounded border border-gray-100">
                        <InputGroup>
                            <InputLabel>{{ t('greeting_heading') }}</InputLabel>
                            <Textarea v-model="simple.heading" :placeholder="t('hi_any_queries_placeholder')" :white="true"></Textarea>
                        </InputGroup>
            
                        <InputGroup>
                            <InputLabel>{{ t('heading_size') }}</InputLabel>
                            <Tabs :options="sizes" v-model="simple.heading_size" :locked="['custom']"></Tabs>
                        </InputGroup>
                        
                        <InputGroup :condition="simple.heading_size == 'custom'">
                            <InputLabel :hints="t('select_icon_size_hint')"> {{ t('custom_heading_size') }} </InputLabel>
                            <div class="w-full flex items-center justify-between gap-2">
                                <input class="formychat-slider" type="range" v-model="simple.heading_size_custom" min="8" max="72">
                                <span class="w-16">{{ simple.heading_size_custom }}px</span>
                            </div>
                        </InputGroup>
                    </div>
    
                    <div class="bg-slate-50 p-5 space-y-5 rounded border border-gray-100">
                        <InputGroup>
                            <InputLabel>{{ t('greeting_message') }}</InputLabel>
                            <Textarea v-model="simple.message" :placeholder="t('hi_any_queries_placeholder')" :white="true"></Textarea>
                        </InputGroup>
            
                        <InputGroup>
                            <InputLabel>{{ t('message_size') }}</InputLabel>
                            <Tabs :options="sizes" v-model="simple.message_size" :locked="['custom']"></Tabs>
                        </InputGroup>

                        <InputGroup :condition="simple.message_size == 'custom'">
                            <InputLabel :hints="t('select_icon_size_hint')"> {{ t('custom_message_size') }} </InputLabel>
                            <div class="w-full flex items-center justify-between gap-2">
                                <input class="formychat-slider" type="range" v-model="simple.message_size_custom" min="8" max="72">
                                <span class="w-16">{{ simple.message_size_custom }}px</span>
                            </div>
                        </InputGroup>

                    </div>
    
                    <div class="bg-slate-50 p-5 space-y-5 rounded border border-gray-100">
                        <InputGroup>
                            <InputLabel locked>{{ t('greeting_colors') }}</InputLabel>
                            <div class="flex items-center gap-4 flex-wrap" :class="{'formychat-locked opacity-60 child:pointer-events-none' : isLocked}">
                                <ColorPicker v-model="simple.heading_color">{{ t('heading_color') }}</ColorPicker>
                                <ColorPicker v-model="simple.message_color">{{ t('message_color') }}</ColorPicker>
                                <ColorPicker v-model="simple.background_color">{{ t('background_color') }}</ColorPicker>
                            </div>
                        </InputGroup>
            
                        <InputGroup>
                            <InputLabel>{{ t('greetings_font_family') }}</InputLabel>
                            <Select v-model="simple.font_family" :options="$widget.contents.fonts" class="w-48"></Select>
                        </InputGroup>
                    </div>
                </div>
                
                <!-- Wave  -->
                <div class="space-y-6" v-if="greetings.template === 'wave'"
                    :class="{ 'opacity-60 pointer-events-none formychat-locked' : isLocked }">
                    <div class="bg-slate-50 p-5 space-y-5 rounded border border-gray-100">
                        <InputGroup class="space-y-3">
                            <Toggle v-model="wave.show_icon">{{ t('show_main_content') }}</Toggle>
                        </InputGroup>

                        <InputGroup :condition="wave.show_icon">
                            <IconUploader v-if="wave.show_icon" locked v-model="wave.icon_url" v-model:custom="wave.icon_url_custom" :default="Image('greetings/hand-wave.svg')" />
                        </InputGroup>

                        <InputGroup :condition="wave.show_icon">
                            <InputLabel>{{ t('position') }}</InputLabel>
                            <Tabs width="135px" :options="greetings.style === 1 ? { before_heading: t('before_heading'), after_heading: t('after_heading'), after_message : t('after_message') } : { before_cta : t('before_cta'), after_cta : t('after_cta') }" :locked="['after_heading', 'after_message']" v-model="wave.icon_position"></Tabs>
                        </InputGroup>
                    </div>

                    <!-- Style 1  -->
                    <div v-if="greetings.style === 1" class="space-y-5">
                        <div class="bg-slate-50 p-5 space-y-5 rounded border border-gray-100">
                            <InputGroup>
                                <InputLabel>{{ t('greeting_heading') }}</InputLabel>
                                <Textarea v-model="wave.heading" :placeholder="t('hi_any_queries_placeholder')" :white="true"></Textarea>
                            </InputGroup>
                
                            <InputGroup>
                                <InputLabel>{{ t('heading_size') }}</InputLabel>
                                <Tabs :options="sizes" v-model="wave.heading_size"></Tabs>
                            </InputGroup>

                            <InputGroup :condition="wave.heading_size == 'custom'">
                                <InputLabel :hints="t('select_icon_size_hint')"> {{ t('custom_heading_size') }} </InputLabel>
                                <div class="w-full flex items-center justify-between gap-2">
                                    <input class="formychat-slider" type="range" v-model="wave.heading_size_custom" min="20" max="150">
                                    <span class="w-16">{{ wave.heading_size_custom }}px</span>
                                </div>
                            </InputGroup>
                        </div>
        
                        <div class="bg-slate-50 p-5 space-y-5 rounded border border-gray-100">
                            <InputGroup>
                                <InputLabel>{{ t('greeting_message') }}</InputLabel>
                                <Textarea v-model="wave.message" :placeholder="t('hi_any_queries_placeholder')" :white="true"></Textarea>
                            </InputGroup>
                
                            <InputGroup>
                                <InputLabel>{{ t('message_size') }}</InputLabel>
                                <Tabs :options="sizes" v-model="wave.message_size"></Tabs>
                            </InputGroup>

                            <InputGroup :condition="wave.message_size == 'custom'">
                                <InputLabel :hints="t('select_icon_size_hint')"> {{ t('custom_message_size') }} </InputLabel>
                                <div class="w-full flex items-center justify-between gap-2">
                                    <input class="formychat-slider" type="range" v-model="wave.message_size_custom" min="20" max="150">
                                    <span class="w-16">{{ wave.message_size_custom }}px</span>
                                </div>
                            </InputGroup>
                        </div>
        
                        <div class="bg-slate-50 p-5 space-y-5 rounded border border-gray-100">
                            <InputGroup>
                                <InputLabel locked>{{ t('greeting_colors') }}</InputLabel>
                                <div class="flex items-center gap-4"  :class="{'formychat-locked opacity-60 child:pointer-events-none' : isLocked}">
                                    <ColorPicker v-model="wave.heading_color">{{ t('heading_color') }}</ColorPicker>
                                    <ColorPicker v-model="wave.message_color">{{ t('message_color') }}</ColorPicker>
                                    <ColorPicker v-model="wave.background_color">{{ t('background_color') }}</ColorPicker>
                                </div>
                            </InputGroup>
                
                            <InputGroup>
                                <InputLabel>{{ t('greetings_font_family') }}</InputLabel>
                                <Select v-model="wave.font_family" :options="$widget.contents.fonts" class="w-48"></Select>
                            </InputGroup>
                        </div>

                        <!-- CTA  -->
                        <div class="bg-slate-50 p-5 space-y-5 rounded border border-gray-100">
                            <InputGroup class="space-y-3">
                                <Toggle v-model="wave.show_cta">{{ t('show_greetings_cta') }}</Toggle>
                            </InputGroup>

                            <InputGroup :condition="wave.show_cta">
                                <InputLabel>{{ t('greeting_cta_text') }}</InputLabel>
                                <Textarea v-model="wave.cta_text" :placeholder="t('hi_any_queries_placeholder')" :white="true"></Textarea>
                            </InputGroup>

                            <InputGroup class="space-y-3" :condition="wave.show_cta">
                                <InputLabel>{{ t('cta_icon') }} <code>png</code>, <code>jpg</code>, <code>svg</code></InputLabel>
                                <IconUploader locked v-model="wave.cta_icon_url" v-model:custom="wave.cta_icon_url_custom" :default="Image('greetings/vector.svg')" />
                            </InputGroup>
                
                            <InputGroup :condition="wave.show_cta">
                                <InputLabel locked>{{ t('cta_style') }}</InputLabel>
                                <div class="flex items-center gap-4" :class="{'formychat-locked opacity-60 child:pointer-events-none' : isLocked}">
                                    <ColorPicker v-model="wave.cta_text_color">{{ t('text_color') }}</ColorPicker>
                                    <ColorPicker v-model="wave.cta_background_color">{{ t('background_color') }}</ColorPicker>
                                </div>
                            </InputGroup>
                
                        </div>
                    </div>

                    <!-- Style 2 -->
                    <div v-if="greetings.style === 2" class="space-y-5">
                        <div class="bg-slate-50 p-5 space-y-5 rounded border border-gray-100">

                            <InputGroup>
                                <Toggle v-model="wave.show_cta">{{ t('show_greeting_cta') }}</Toggle>
                            </InputGroup>

                            <InputGroup :condition="wave.show_cta">
                                <InputLabel>{{ t('greeting_cta_heading') }}</InputLabel>
                                <Textarea v-model="wave.cta_heading" :placeholder="t('hi_any_queries_placeholder')" :white="true"></Textarea>
                            </InputGroup>
                
                            <InputGroup :condition="wave.show_cta">
                                <InputLabel>{{ t('cta_heading_size') }}</InputLabel>
                                <Tabs :options="sizes" v-model="wave.cta_heading_size"></Tabs>
                            </InputGroup>

                            <InputGroup :condition="wave.show_cta && wave.cta_heading_size == 'custom'">
                                <InputLabel :hints="t('select_icon_size_hint')"> {{ t('custom_cta_heading_size') }} </InputLabel>
                                <div class="w-full flex items-center justify-between gap-2">
                                    <input class="formychat-slider" type="range" v-model="wave.cta_heading_size_custom" min="20" max="150">
                                    <span class="w-16">{{ wave.cta_heading_size_custom }}px</span>
                                </div>
                            </InputGroup>

                            <InputGroup :condition="wave.show_cta">
                                <InputLabel>{{ t('greeting_cta_message') }}</InputLabel>
                                <Textarea v-model="wave.cta_message" :placeholder="t('hi_any_queries_placeholder')" :white="true"></Textarea>
                            </InputGroup>
                
                            <InputGroup :condition="wave.show_cta">
                                <InputLabel>{{ t('cta_message_size') }}</InputLabel>
                                <Tabs :options="sizes" v-model="wave.cta_message_size"></Tabs>
                            </InputGroup>

                            <InputGroup :condition="wave.show_cta && wave.cta_message_size == 'custom'">
                                <InputLabel :hints="t('select_icon_size_hint')"> {{ t('custom_cta_message_size') }} </InputLabel>
                                <div class="w-full flex items-center justify-between gap-2">
                                    <input class="formychat-slider" type="range" v-model="wave.cta_message_size_custom" min="20" max="150">
                                    <span class="w-16">{{ wave.cta_message_size_custom }}px</span>
                                </div>
                            </InputGroup>

                        </div>

                        
                        <transition name="slide">
                            <div v-if="wave.show_cta" class="bg-slate-50 p-5 space-y-5 rounded border border-gray-100">
                                <InputGroup>
                                    <InputLabel>{{ t('cta_colors') }}</InputLabel>
                                    <div class="flex items-center gap-4">
                                        <ColorPicker v-model="wave.cta_heading_color">{{ t('heading_color') }}</ColorPicker>
                                        <ColorPicker v-model="wave.cta_message_color">{{ t('message_color') }}</ColorPicker>
                                        <ColorPicker v-model="wave.cta_background_color">{{ t('background_color') }}</ColorPicker>
                                    </div>
                                </InputGroup>

                                <InputGroup>
                                    <InputLabel>{{ t('greeting_font_family') }}</InputLabel>
                                    <Select v-model="wave.font_family" :options="$widget.contents.fonts" class="w-48"></Select>
                                </InputGroup>
                            </div>
                        </transition>
                    </div>
                </div>
            </Group>

            <Group :title="t('greeting_behavior')" :gap="false">
                <InputLabel>{{ t('on_click_action') }}</InputLabel>
                <div class="flex flex-col gap-2.5 child:cursor-pointer">
                    <label class="flex items-center gap-4 group" 
                    v-for="(label, action) in greetingActions"
                    @click.prevent="(isLocked && action == 'redirect') ? null : greetings.on_click = action"
                    :class="{ 'text-indigo-500' : greetings.on_click == action, }"
                    > 
                        <div class="w-5 h-5 bg-white border-[5px] rounded-full  transition" :class="{ 
                            'border-indigo-500' : greetings.on_click == action, 
                            'border-gray-100' : greetings.on_click !== action,
                            'group-hover:border-indigo-500' : greetings.on_click !== action && !isLocked,
                            'formychat-locked' : isLocked && action === 'redirect'
                        }"><span></span></div> <span :class="{
                            'opacity-60 formychat-locked' : isLocked && action === 'redirect'}">{{ label }}</span>
                        <ProBadge v-if="action === 'redirect'" />
                    </label>
                </div>
                
            </Group>
        </InputGroup>
    </div>
</template>
