<script setup>
/**
 * A channel's logo glyph, tinted with any color through a CSS mask.
 *
 * Size comes from `size`, or from classes on the component (e.g. class="w-6 h-6").
 *
 * @since 2.16.0
 */
import { computed } from 'vue';
import { CHANNELS, CHANNEL_GLYPH_COLOR, isHexColor } from '../utility/channels';

const props = defineProps({
	// whatsapp | telegram. Unknown shows WhatsApp.
	channel: { type: String, default: 'whatsapp' },
	// Glyph color. Anything but a valid hex falls back to white.
	color: { type: String, default: '' },
	// CSS size (e.g. '24px', '50%'). Empty = sized by classes.
	size: { type: String, default: '' },
	// Glyph image to use instead of the bundled one.
	src: { type: String, default: '' },
});

const key = computed(() => (CHANNELS.includes(props.channel) ? props.channel : 'whatsapp'));
const url = computed(() => props.src || (window.formychat_admin_vars?.public || '') + `images/${key.value}-glyph.svg`);

const style = computed(() => {
	const safe = String(url.value).replace(/["\\\s]/g, encodeURIComponent);
	const mask = `url("${safe}") center / contain no-repeat`;
	return {
		...(props.size ? { width: props.size, height: props.size } : {}),
		backgroundColor: isHexColor(props.color) ? props.color : CHANNEL_GLYPH_COLOR,
		WebkitMask: mask,
		mask,
	};
});
</script>
<template>
	<span class="inline-block shrink-0" :style="style" aria-hidden="true"></span>
</template>
