// Display order in the picker: free icons first (the default first), then FormyChat Ultimate icons.
export const LAUNCHER_STYLES = [
    { key: 'chat', shape: 'circle', color: LEGACY_LAUNCHER_COLOR, pro: false },
    { key: 'dots', shape: 'circle', color: '#0284C7', pro: false },
    { key: 'round', shape: 'circle', color: '#F43F5E', pro: false },
    { key: 'bubble', shape: 'circle', color: '#9D98FF', pro: true },
    { key: 'sparkle', shape: 'squircle', color: '#5A67D8', pro: true, box: 58 },
    { key: 'form', shape: 'circle', color: '#1DBF48', pro: true, box: 58 },
    { key: 'help', shape: 'pill', color: '#1A7F37', pro: true },
].map(style => ({ ...style, glyph: GLYPHS[style.key] }))

const toHex = value => {
    const hex = String(value || '').trim().toUpperCase()
    return /^#([0-9A-F]{3}){1,2}$/.test(hex) ? hex : ''
}

const isOn = value => !(value === false || value === 0 || value === '0' || value === 'false' || value === '' || value == null)

/**
 * Color of an icon: from the icons PHP sent (FormyChat Ultimate may add or change them), else the catalog.
 */
export const styleColor = (key, icons = {}) => {
    return toHex(icons?.[key]?.color)
        || toHex(LAUNCHER_STYLES.find(style => style.key === key)?.color)
        || LEGACY_LAUNCHER_COLOR
}

/**
 * Whether the saved color is one kept from before icons had their own color (or picked in FormyChat Ultimate).
 */
export const hasSavedColor = (launcher = {}) => {
    const saved = toHex(launcher.color)
    return Boolean(saved) && (saved !== LEGACY_LAUNCHER_COLOR || isOn(launcher.color_custom))
}

/**
 * Launcher color shown in the admin preview. Mirrors App::resolve_launcher_color()
 * and FormyChat Ultimate's `formychat_launcher_color` callback.
 *
 * @param {object}   launcher Saved launcher settings.
 * @param {object}   options
 * @param {object}   options.icons   Launcher icons PHP sent.
 * @param {string[]} options.presets Launcher preset colors PHP sent.
 * @param {boolean}  options.premium Whether FormyChat Ultimate is active (display only).
 * @returns {string}
 */
export const resolveLauncherColor = (launcher = {}, { icons = {}, presets = [], premium = false } = {}) => {
    const key = icons[launcher.icon] ? launcher.icon : 'chat'
    const fallback = styleColor(key, icons)
    const saved = toHex(launcher.color)

    if (premium && saved && (isOn(launcher.color_custom) || saved !== LEGACY_LAUNCHER_COLOR)) {
        return saved
    }

    // A preset color is free; any other saved color keeps showing the old default.
    const isPreset = presets.map(toHex).includes(saved)
    if (saved && isPreset && (isOn(launcher.color_custom) || saved !== LEGACY_LAUNCHER_COLOR)) {
        return saved
    }

    if (saved && saved !== LEGACY_LAUNCHER_COLOR) {
        return LEGACY_LAUNCHER_COLOR
    }

    return fallback
}

/**
 * Launcher symbol color shown in the admin preview ('' = white, today's look).
 * Mirrors App::resolve_widget_icons() and the `formychat_launcher_glyph_color` filter:
 * FormyChat shows a saved preset color (else white), FormyChat Ultimate shows any saved color.
 *
 * @param {object}   launcher Saved launcher settings.
 * @param {object}   options
 * @param {string[]} options.presets Launcher symbol preset colors PHP sent.
 * @param {boolean}  options.premium Whether FormyChat Ultimate is active (display only).
 * @returns {string}
 */
export const resolveLauncherGlyphColor = (launcher = {}, { presets = [], premium = false } = {}) => {
    const saved = toHex(launcher.glyph_color)
    if (premium) return saved
    return presets.map(toHex).includes(saved) ? saved : ''
}

/**
 * Inline style that draws an icon image tinted with a color through a CSS mask.
 *
 * @param {string} url   Icon image URL.
 * @param {string} color Hex color.
 * @returns {object}
 */
export const tintedIconStyle = (url, color) => {
    const safe = String(url || '').replace(/["\\s]/g, encodeURIComponent)
    const mask = `url("${safe}") center / contain no-repeat`
    return {
        backgroundColor: color,
        WebkitMask: mask,
        mask,
    }
}

/**
 * Inline glyph SVG recolored from white to a color ('' keeps white).
 *
 * @param {string} glyph Inline SVG markup from LAUNCHER_STYLES.
 * @param {string} color Hex color.
 * @returns {string}
 */
export const tintGlyph = (glyph, color) => {
    const hex = toHex(color)
    return hex ? String(glyph || '').replace(/"#fff"/gi, `"${hex}"`) : String(glyph || '')
}
