<script setup>
import { ref, computed, reactive, onMounted, onBeforeUnmount, watch } from 'vue';
import { storeToRefs } from 'pinia';
import { useWidgets } from '@store/widgets';
import { Group, Tabs, InputLabel, InputGroup, Text, Button, Select, Toggle, NewBadge, Textarea, ColorPicker, Spin, MessagePreset, Tooltip, ProBadge, LockedHover, ChannelGlyph } from '@components';
import API from '@util/API'
import { LAUNCHER_STYLES, LEGACY_LAUNCHER_COLOR, styleColor, hasSavedColor, resolveLauncherColor, resolveLauncherGlyphColor, tintedIconStyle, tintGlyph } from '@util/launcher'
import { useTranslation } from '../../composables/useTranslation';
import { useUpgrade } from '@store/Upgrade';
import { CHANNEL_COLORS, channelGlyphColor } from '@util/channels'
import StyleThumb from './channels/StyleThumb.vue'

const { t } = useTranslation();

const state = reactive({})
const $widget = useWidgets();
const { fields: widgetFieldsRef } = storeToRefs($widget);

const formychat_admin_vars = window.formychat_admin_vars || {};

// reCAPTCHA config (only visible when FormyChat form is selected).
// Use getter to read current values - formychat_admin_vars is updated after save.
const getRc = () => (formychat_admin_vars.recaptcha || {})
const recaptcha = reactive({
    enabled: getRc().enabled || false,
    site_key: getRc().site_key || '',
    secret_key: '',
    version: getRc().version || 'v2'
});

const recaptchaVersionOptions = computed(() => [
    { value: 'v2', name: t('recaptcha_version_v2'), label: t('recaptcha_version_v2') },
    { value: 'v3', name: t('recaptcha_version_v3'), label: t('recaptcha_version_v3') }
]);

const SECRET_KEY_MASK = '••••••••••••••••';
const userClearedSecretKey = ref(false);
const secretKeyDisplay = computed({
    get() {
        if ($widget.recaptchaSecretKeyConfigured && !recaptcha.secret_key && !userClearedSecretKey.value) {
            return SECRET_KEY_MASK;
        }
        return recaptcha.secret_key;
    },
    set(val) {
        const isMaskOrEmpty = val === '' || val === SECRET_KEY_MASK || /^•+$/.test(val);
        recaptcha.secret_key = isMaskOrEmpty ? '' : val;
        userClearedSecretKey.value = isMaskOrEmpty;
    }
});

// Cloudflare Turnstile (same scope as reCAPTCHA; only one should be active).
const getTs = () => (formychat_admin_vars.turnstile || {})
const turnstile = reactive({
    enabled: getTs().enabled || false,
    site_key: getTs().site_key || '',
    secret_key: ''
})
const userClearedTurnstileSecret = ref(false)
const turnstileSecretDisplay = computed({
    get() {
        if ($widget.turnstileSecretKeyConfigured && !turnstile.secret_key && !userClearedTurnstileSecret.value) {
            return SECRET_KEY_MASK;
        }
        return turnstile.secret_key;
    },
    set(val) {
        const isMaskOrEmpty = val === '' || val === SECRET_KEY_MASK || /^•+$/.test(val);
        turnstile.secret_key = isMaskOrEmpty ? '' : val;
        userClearedTurnstileSecret.value = isMaskOrEmpty;
    }
})

const errors = computed(() => $widget.errors || {});

const whatsapp = computed(() => $widget.currentWidget?.config?.whatsapp || {})
const icon = computed(() => $widget.currentWidget?.config?.icon || {})
const form = computed(() => $widget.currentWidget?.config?.form || {})
const cta = computed(() => $widget.currentWidget?.config?.cta || {})
const email = computed(() => $widget.currentWidget?.config?.email || {})
const channels = computed(() => $widget.currentWidget?.config?.channels || { enabled: ['whatsapp'], launcher: {} })
const launcher = computed(() => channels.value.launcher || {})
const hasManyChannels = computed(() => (channels.value.enabled || []).length > 1)
const telegram = computed(() => $widget.currentWidget?.config?.telegram || {})
const hasTelegram = computed(() => (channels.value.enabled || []).includes('telegram'))
const hasWhatsapp = computed(() => (channels.value.enabled || []).includes('whatsapp'))
// Which channel's form text is being edited.
const textChannel = ref(hasWhatsapp.value ? 'whatsapp' : 'telegram')
// The preview shows the form of the channel whose text is being edited.
watch(textChannel, channel => { $widget.previewChannel = channel }, { immediate: true })
onBeforeUnmount(() => { $widget.previewChannel = '' })

// Free launcher icons come from FormyChat; FormyChat Ultimate adds its own through a filter.
// Every icon is listed; one this site does not offer yet shows locked.
const launcherIcons = formychat_admin_vars.data?.launcher_icons || {}
const launcherColors = formychat_admin_vars.data?.launcher_colors || [LEGACY_LAUNCHER_COLOR]
const launcherColorOptions = { icons: launcherIcons, presets: launcherColors, premium: !!formychat_admin_vars.is_premium }
const launcherStyles = computed(() => {
    const known = LAUNCHER_STYLES.map(style => ({
        ...style,
        label: launcherIcons[style.key]?.label || t('launcher_icon_' + style.key),
        text: style.shape === 'pill' ? (launcherIcons[style.key]?.text || t('launcher_icon_' + style.key)) : '',
        color: styleColor(style.key, launcherIcons),
        locked: !launcherIcons[style.key],
    }))
    // Icons added by other code through `formychat_launcher_icons`.
    const extra = Object.keys(launcherIcons)
        .filter(key => !LAUNCHER_STYLES.some(style => style.key === key))
        .map(key => ({ ...launcherIcons[key], key, glyph: '', color: styleColor(key, launcherIcons), locked: false }))
    return [...known, ...extra]
})
const launcherUsesSavedColor = computed(() => hasSavedColor(launcher.value))
const launcherColor = computed(() => resolveLauncherColor(launcher.value, launcherColorOptions))
// Color each tile would get once picked.
const launcherTileColor = style => style.locked ? style.color : resolveLauncherColor({ ...launcher.value, icon: style.key }, launcherColorOptions)
const selectLauncherIcon = style => {
    // Locked icons: the click reaches the upgrade prompt through .formychat-locked.
    if (style.locked) return
    launcher.value.icon = style.key
    // A picked icon replaces an uploaded one.
    if (launcher.value.icon_url) launcher.value.icon_url = ''
}
// Own launcher image with 2+ channels: FormyChat Ultimate saves and draws it.
const launcherUpload = computed(() => launcher.value.icon_url || '')
// Inline launcher SVGs fill their box (set inline so it never depends on generated utility classes).
const fillGlyph = svg => String(svg || '').replace('<svg ', '<svg width="100%" height="100%" style="display:block" ')
// Shape of the launcher drawn in the Widget style thumbnails (rounded square for Sparkle chat).
const thumbLauncherShape = computed(() => {
    const style = launcherStyles.value.find(item => item.key === launcher.value.icon) || {}
    return !launcherUpload.value && style.shape === 'squircle' ? 'squircle' : 'circle'
})
const uploadLauncherIcon = () => {
    if (isLocked.value || !window.wp?.media) return
    window.wp.media.editor.send.attachment = (props, attachment) => {
        launcher.value.icon_url = attachment.url
    }
    window.wp.media.editor.open()
}
// Presets are free; any other color (the picker) is FormyChat Ultimate. `color_custom` keeps even the old default color.
const isLauncherPreset = color => launcherColors.some(preset => sameColor(preset, color))
const pickLauncherColor = color => {
    if (isLocked.value && !isLauncherPreset(color)) return
    launcher.value.color = color
    launcher.value.color_custom = true
}
const useLauncherStyleColor = () => {
    launcher.value.color = LEGACY_LAUNCHER_COLOR
    launcher.value.color_custom = false
}
const sameColor = (a, b) => String(a || '').toUpperCase() === String(b || '').toUpperCase()
const launcherUsesPreset = computed(() => launcherUsesSavedColor.value && launcherColors.some(color => sameColor(color, launcher.value.color)))
const launcherUsesCustom = computed(() => launcherUsesSavedColor.value && !launcherUsesPreset.value)
const onCustomLauncherColor = event => pickLauncherColor(event.target.value)
// Launcher symbol color. Empty = white, as before. Presets are free; the picker is FormyChat Ultimate.
const LAUNCHER_GLYPH_COLORS = formychat_admin_vars.data?.launcher_glyph_colors || ['#111827', '#4F46E5', '#E11D48', '#F59E0B']
const launcherGlyphColor = computed(() => resolveLauncherGlyphColor(launcher.value, { presets: LAUNCHER_GLYPH_COLORS, premium: !!formychat_admin_vars.is_premium }))
const launcherGlyphUsesPreset = computed(() => !!launcher.value.glyph_color && LAUNCHER_GLYPH_COLORS.some(color => sameColor(color, launcher.value.glyph_color)))
const launcherGlyphUsesCustom = computed(() => !!launcher.value.glyph_color && !launcherGlyphUsesPreset.value)
const pickLauncherGlyphColor = color => {
    if (isLocked.value && !LAUNCHER_GLYPH_COLORS.some(preset => sameColor(preset, color))) return
    launcher.value.glyph_color = color
}
const useDefaultLauncherGlyphColor = () => {
    launcher.value.glyph_color = ''
}
const onCustomLauncherGlyphColor = event => pickLauncherGlyphColor(event.target.value)
// Chat window header color (FormyChat Ultimate). Empty = the launcher color.
const pickHeaderColor = color => {
    if (isLocked.value) return
    launcher.value.header_color = color
}

// Widget styles. Buttons comes with FormyChat; FormyChat Ultimate adds the others through
// `formychat_channel_list_styles`. Every style is listed; one this site does not offer shows locked.
// Buttons covers two saved values: `stack` (Vertical) and `row` (Horizontal).
const listStyleData = formychat_admin_vars.data?.channel_list_styles || { stack: {} }
const WIDGET_STYLES = ['stack', 'card', 'grid', 'menu', 'bubble', 'chat', 'corner']
const listStyles = computed(() => WIDGET_STYLES.map(key => ({
    key,
    locked: !listStyleData[key],
})))
const usesButtons = computed(() => ['stack', 'row'].includes(launcher.value.style || 'stack'))
const isStyleSelected = key => key === 'stack' ? usesButtons.value : launcher.value.style === key
const directions = computed(() => [
    { key: 'stack', label: t('vertical'), locked: !listStyleData.stack },
    { key: 'row', label: t('horizontal'), locked: !listStyleData.row },
])
const selectDirection = direction => {
    // Locked: the click reaches the upgrade prompt through .formychat-locked.
    if (direction.locked) return
    launcher.value.style = direction.key
}
const listUsesTitle = computed(() => ['card', 'chat', 'grid', 'bubble'].includes(launcher.value.style))
const listUsesMessage = computed(() => ['card', 'chat'].includes(launcher.value.style))
const listUsesHeaderColor = computed(() => launcher.value.style === 'chat')
const listUsesSub = computed(() => ['card', 'chat', 'bubble'].includes(launcher.value.style))
// The Widget title & subtitle section shows only for styles with a title.
const listHasText = computed(() => listUsesTitle.value || listUsesMessage.value || listUsesHeaderColor.value)
const channelNames = { whatsapp: 'WhatsApp', telegram: 'Telegram' }
// With one channel the button is that channel's icon, set in the Channels tab.
const singleChannel = computed(() => (channels.value.enabled || [])[0] === 'telegram' ? 'telegram' : 'whatsapp')
// Channel icon: its color (Channels tab) or brand color, and its own uploaded image when there is one
// (Telegram: telegram.icon_url; WhatsApp: a custom icon.image_url, not the bundled logo).
const isBundledImage = url => !url || /\/images\/(whatsapp|telegram)\.svg$/.test(url)
const channelIcon = channel => {
    const config = $widget.currentWidget?.config || {}
    return {
        color: config[channel]?.icon_color || CHANNEL_COLORS[channel],
        glyphColor: channelGlyphColor(config, channel),
        image: channel === 'telegram'
            ? (config.telegram?.icon_url || '')
            : (isBundledImage(icon.value.image_url) ? '' : icon.value.image_url),
    }
}
// Leaving the tab never fires focusout, so drop the preview mark here.
onBeforeUnmount(() => { $widget.previewFocus = '' })
const glyph = channel => formychat_admin_vars.public + `images/${channel}-glyph.svg`
// Widget style cards: as many per row as fit (all 7 on wide screens), wrapping on narrow ones. Inline so it never depends on generated utility classes.
// Widget style cards: 7 in one row when they fit, else 4 + 3, else 3 per row, so no card sits alone.
const styleGrid = ref(null)
const styleGridWidth = ref(0)
let styleGridObserver = null
onMounted(() => {
    if (typeof ResizeObserver === 'undefined') return
    styleGridObserver = new ResizeObserver(([entry]) => { styleGridWidth.value = entry.contentRect.width })
    watch(styleGrid, el => { styleGridObserver.disconnect(); if (el) styleGridObserver.observe(el) }, { immediate: true })
})
onBeforeUnmount(() => styleGridObserver?.disconnect())
const fitsCols = (n, min) => styleGridWidth.value >= n * min + (n - 1) * 10
const styleGridStyle = computed(() => {
    const cols = !styleGridWidth.value || fitsCols(7, 96) ? 7 : (fitsCols(4, 96) ? 4 : 3)
    return { display: 'grid', gridTemplateColumns: `repeat(${cols}, minmax(0, 1fr))`, gap: '10px' }
})
// The widget's own channels, drawn in the Widget style thumbnails.
const styleChannels = computed(() => (channels.value.enabled || []).map(key => ({
    key,
    label: $widget.currentWidget?.config?.[key]?.list_label || channelNames[key],
    sub: $widget.currentWidget?.config?.[key]?.list_sub || '',
    glyph: glyph(key),
    ...channelIcon(key),
})))
const selectListStyle = style => {
    // Locked styles: the click reaches the upgrade prompt through .formychat-locked.
    if (style.locked) return
    // Buttons keeps the direction already saved.
    if (style.key === 'stack' && usesButtons.value) return
    launcher.value.style = style.key
}

// Forms.
const cf7 = computed(() => $widget.currentWidget?.config?.cf7 || {})

const sizes = computed(() => ({
    'small': t('small'),
    'medium': t('medium'),
    'large': t('large'),
    'custom': t('custom'),
}));

const positions = computed(() => ({
    'left': t('left'),
    'right': t('right'),
    'custom': t('custom'),
}));

const admin_email = formychat_admin_vars.site.admin_email || '';

const allForms = formychat_admin_vars.data.forms || {}; 

// Form Mode.
const setFormMode = mode => {

    // Locked (Pro) form integration — show upgrade prompt instead of switching.
    if (allForms[mode]?.locked && !formychat_admin_vars.is_premium) {
        return useUpgrade().show()
    }

    const customForms = Object.keys(allForms).filter(mode => mode !== 'formychat');

    // Reset errors.
    customForms.forEach(mode => {
        $widget.setError(mode + 'NotActivated', false)
        $widget.setError(mode + 'NotInstalled', false)
    })

    if (mode === 'formychat') {
        form.value.mode = mode
        $widget.fetchFields()
        return;
    }

    // Check if the form is installed and activated.
    if (customForms.includes(mode)) {
        if (!formychat_admin_vars.additional[mode].is_installed) {
            return $widget.setError(mode + 'NotInstalled')
        }

        if (!formychat_admin_vars.additional[mode].is_active) {
            return $widget.setError(mode + 'NotActivated')
        }

        // Set form.mode_form_id if not set.
        if (!form.value[mode + '_id']) {
            form.value[mode + '_id'] = $widget.contents.forms[mode][0]?.value || ''
        }
    }

    // Load form fields.
    form.value.mode = mode
    $widget.fetchFields()
}

const isLocked = computed(() => !formychat_admin_vars.is_premium)

const toggleDeviceVisibility = (device) => {
    if (isLocked.value) return

    // Get current values (default to true if undefined)
    const currentDesktop = icon.value.show_on_desktop !== false
    const currentMobile = icon.value.show_on_mobile !== false

    if (device === 'desktop') {
        // Don't allow disabling if mobile is also disabled
        if (currentDesktop && !currentMobile) return
        icon.value.show_on_desktop = !currentDesktop
    } else {
        // Don't allow disabling if desktop is also disabled
        if (currentMobile && !currentDesktop) return
        icon.value.show_on_mobile = !currentMobile
    }
}


// Activate CF7
const activatePlugin = async (plugin = 'cf7', action = 'install') => {
    state.pluginActivating = action;

    await API.get('action?action=activate_plugin&plugin=' + plugin);

    formychat_admin_vars.additional[plugin].is_active = true
    formychat_admin_vars.additional[plugin].is_installed = true

    setFormMode(plugin)
    await $widget.fetchContents();
    form.value[plugin + '_form_id'] = $widget.contents.forms[plugin].length > 0 ? $widget.contents.forms[plugin][0]?.value : ''
    // Load CF7 form.
    state.pluginActivating = false;
}

const YouTubeId = ref('')

// Forms.
const forms = formychat_admin_vars.data.forms || {}

// Sync recaptcha to store when FormyChat form is selected (for save).
watch(() => form.value.mode, (mode) => {
    if (mode === 'formychat') {
        const rc = getRc()
        recaptcha.enabled = rc.enabled || false
        recaptcha.site_key = rc.site_key || ''
        recaptcha.version = rc.version || 'v2'
        recaptcha.secret_key = ''
        userClearedSecretKey.value = false
        $widget.setRecaptchaOptions(recaptcha)

        const ts = getTs()
        turnstile.enabled = ts.enabled || false
        turnstile.site_key = ts.site_key || ''
        turnstile.secret_key = ''
        userClearedTurnstileSecret.value = false
        $widget.setTurnstileOptions(turnstile)
    }
}, { immediate: true })

watch(recaptcha, (val) => {
    if (form.value.mode === 'formychat') {
        $widget.setRecaptchaOptions({ ...val })
    }
}, { deep: true })

watch(turnstile, (val) => {
    if (form.value.mode === 'formychat') {
        $widget.setTurnstileOptions({ ...val })
    }
}, { deep: true })

watch(() => recaptcha.enabled, (on) => {
    if (form.value.mode !== 'formychat') return
    if (on && turnstile.enabled) {
        turnstile.enabled = false
    }
})

watch(() => turnstile.enabled, (on) => {
    if (form.value.mode !== 'formychat') return
    if (on && recaptcha.enabled) {
        recaptcha.enabled = false
    }
})

const defaultCustomDropdown = () => ({
    enabled: true,
    label: 'Dropdown',
    name: 'dropdown',
    required: false,
    placeholder: '- Select -',
    position: 'before_message',
    default_value: '',
    options: [
        { value: 'option_1', label: 'Option 1' },
        { value: 'option_2', label: 'Option 2' },
    ],
})

const ensureCustomDropdown = () => {
    if (!form.value.custom_dropdown || typeof form.value.custom_dropdown !== 'object') {
        form.value.custom_dropdown = defaultCustomDropdown()
    }
    if (!Array.isArray(form.value.custom_dropdown.options)) {
        form.value.custom_dropdown.options = []
    }
    if (form.value.custom_dropdown.default_value === undefined) {
        form.value.custom_dropdown.default_value = ''
    }
}

const customDropdownPositionOptions = computed(() => [
    { value: 'after_name', name: t('custom_dropdown_position_after_name'), label: t('custom_dropdown_position_after_name') },
    { value: 'after_email', name: t('custom_dropdown_position_after_email'), label: t('custom_dropdown_position_after_email') },
    { value: 'after_phone', name: t('custom_dropdown_position_after_phone'), label: t('custom_dropdown_position_after_phone') },
    { value: 'before_message', name: t('custom_dropdown_position_before_message'), label: t('custom_dropdown_position_before_message') },
])

const formychatMessagePresetFields = computed(() => {
    ensureCustomDropdown()
    const raw = widgetFieldsRef.value
    const base = raw && typeof raw === 'object' ? { ...raw } : {}
    const fd = form.value.custom_dropdown
    if (form.value.mode === 'formychat' && fd?.enabled && fd.name) {
        const lbl = fd.label && String(fd.label).trim() ? fd.label : fd.name
        base[fd.name] = lbl
    }
    return base
})

const addCustomDropdownOption = () => {
    ensureCustomDropdown()
    const n = form.value.custom_dropdown.options.length + 1
    form.value.custom_dropdown.options.push({ label: `Option ${n}`, value: `option_${n}` })
}

const dropdownMinOptionToast = ref(false)
let dropdownToastTimer = null

// Controls visibility of the "value" column in the options list.
// When hidden, each option's value is kept in sync with its label.
const showValueFields = ref(false)

watch(showValueFields, (show) => {
    if (!show) {
        form.value.custom_dropdown?.options?.forEach((opt) => {
            opt.value = opt.label
        })
    }
})

watch(
    () => form.value.custom_dropdown?.options?.map((o) => o.label),
    (newLabels) => {
        if (!showValueFields.value && newLabels) {
            newLabels.forEach((label, idx) => {
                if (form.value.custom_dropdown?.options?.[idx]) {
                    form.value.custom_dropdown.options[idx].value = label
                }
            })
        }
    }
)

const removeCustomDropdownOption = (idx) => {
    ensureCustomDropdown()
    if (form.value.custom_dropdown.options.length <= 1) {
        dropdownMinOptionToast.value = true
        clearTimeout(dropdownToastTimer)
        dropdownToastTimer = setTimeout(() => { dropdownMinOptionToast.value = false }, 3000)
        return
    }
    form.value.custom_dropdown.options.splice(idx, 1)
}

const DROPDOWN_TEMPLATE_LINE_RE = /^\s*Dropdown:\s*\{[^}]+\}\s*$/

const stripDropdownTemplateLines = (text) => {
    if (!text || typeof text !== 'string') {
        return ''
    }
    const lines = text.split('\n')
    const filtered = lines.filter((line) => !DROPDOWN_TEMPLATE_LINE_RE.test(line))
    return filtered.join('\n').replace(/\n{3,}/g, '\n\n')
}

const appendDropdownTemplateLine = (text, fieldKey) => {
    const key = (fieldKey && String(fieldKey).trim()) || 'dropdown'
    const line = `Dropdown: {${key}}`
    const current = typeof text === 'string' ? text : ''
    const trimmedLines = current.split('\n').map((l) => l.trimEnd())
    if (trimmedLines.some((l) => l.trim() === line)) {
        return current
    }
    if (!current.length) {
        return `${line}\n`
    }
    const endsWithNl = current.endsWith('\n')
    return `${current}${endsWithNl ? '' : '\n'}${line}\n`
}

watch(
    () => !!form.value.custom_dropdown?.enabled,
    (enabled, wasEnabled) => {
        if (form.value.mode !== 'formychat') {
            return
        }
        if (wasEnabled === undefined) {
            return
        }
        ensureCustomDropdown()
        const tmpl = whatsapp.value.message_template
        if (enabled) {
            const key = form.value.custom_dropdown.name || 'dropdown'
            whatsapp.value.message_template = appendDropdownTemplateLine(tmpl, key)
        } else {
            whatsapp.value.message_template = stripDropdownTemplateLines(tmpl)
        }
    }
)

watch(() => form.value.mode, (mode) => {
    if (mode === 'formychat') {
        ensureCustomDropdown()
    }
}, { immediate: true })

watch(() => $widget.currentWidget?.id, () => {
    ensureCustomDropdown()
})

// Adjust cf7_id.
onMounted(() => {
    ensureCustomDropdown()
    if (cf7.value.form_id) {
        form.value.cf7_id = cf7.value.form_id

        // Reset cf7_id.
        cf7.value.form_id = ''
    }

    if (form.value.mode === 'formychat') {
        const rc = getRc()
        recaptcha.enabled = rc.enabled || false
        recaptcha.site_key = rc.site_key || ''
        recaptcha.version = rc.version || 'v2'
        userClearedSecretKey.value = false
        $widget.setRecaptchaOptions(recaptcha)

        const ts = getTs()
        turnstile.enabled = ts.enabled || false
        turnstile.site_key = ts.site_key || ''
        turnstile.secret_key = ''
        userClearedTurnstileSecret.value = false
        $widget.setTurnstileOptions(turnstile)
    }

    $widget.fetchFields()
})


</script>
<template>
    <div class="w-full h-full">
        <div class="flex flex-col gap-10 w-full">
            <!-- Appearance: how the chat button looks and how channels open from it -->
            <Group :title="t('appearance')" :gap="false">
                <p class="m-0 -mt-3 text-sm text-slate-500">{{ t('appearance_hint') }}</p>
                <!-- One channel: the button is that channel's icon, set in the Channels tab -->
                <div v-if="!hasManyChannels" class="flex flex-wrap items-center gap-3">
                    <span class="w-11 h-11 rounded-full grid place-items-center shrink-0 overflow-hidden"
                        :style="{ background: channelIcon(singleChannel).image ? 'transparent' : channelIcon(singleChannel).color }">
                        <img v-if="channelIcon(singleChannel).image" :src="channelIcon(singleChannel).image" class="w-full h-full object-cover" alt="">
                        <ChannelGlyph v-else :channel="singleChannel" :src="glyph(singleChannel)" :color="channelIcon(singleChannel).glyphColor" class="w-6 h-6" />
                    </span>
                    <span class="text-sm text-slate-700">{{ channelNames[singleChannel] }}</span>
