<script setup>
import { computed, ref, onMounted, reactive, watch } from 'vue';
import { useWidgets } from '@store/widgets';
import { Editable, Select, Button, Spin, ChannelGlyph } from '@components';
import { channelGlyphColor, isHexColor, hasDestination, channelLabel, channelRowLabel } from '../../utility/channels';
import { useTranslation } from '../../composables/useTranslation';
import { resolveLauncherColor, resolveLauncherGlyphColor, tintedIconStyle } from '@util/launcher';
import ListStyleLive from './channels/ListStyleLive.vue';

const $widget = useWidgets();
const { t } = useTranslation();

const whatsapp = computed(() => $widget.currentWidget?.config?.whatsapp || {})
const icon = computed(() => $widget.currentWidget?.config?.icon || {})
const cta = computed(() => $widget.currentWidget?.config?.cta || {})
const form = computed(() => $widget.currentWidget?.config?.form || {})

const greetings = computed(() => $widget.currentWidget?.config?.greetings || {})
const simple = computed(() => $widget.currentWidget.config?.greetings?.templates?.simple || {})
const wave = computed(() => $widget.currentWidget.config?.greetings?.templates?.wave || {})

const device = ref($widget.isMobile ? 'phone' : 'desktop');

// Channels.
const channelColors = { whatsapp: '#25D366', telegram: '#229ED9' }
const channelNames = { whatsapp: 'WhatsApp', telegram: 'Telegram' }
// Channels the site shows on the previewed device (getEnabledChannels() in the frontend): a channel
// switched off for this device drops out. One with no number or username drops out too, except
// on the Channels tab, where it is still being set up.
const savedChannels = computed(() => $widget.currentWidget?.config?.channels?.enabled || ['whatsapp'])
const deviceChannels = computed(() => {
    const config = $widget.currentWidget?.config || {}
    const onDesktop = device.value === 'desktop'
    return savedChannels.value.filter((channel) => {
        const settings = config[channel] || {}
        if (onDesktop && settings.show_on_desktop === false) return false
        if (!onDesktop && settings.show_on_mobile === false) return false
        return $widget.isTab('channels') || hasDestination(config, channel)
    })
})
const enabledChannels = computed(() => deviceChannels.value.length ? deviceChannels.value : savedChannels.value.slice(0, 1))
const isMulti = computed(() => enabledChannels.value.length > 1)

// Why the site shows no widget on the previewed device ('' = it shows): the widget's own
// Show on switch (Size and position), or no channel left for this device.
const hiddenReason = computed(() => {
    const onDesktop = device.value === 'desktop'
    if (onDesktop && icon.value.show_on_desktop === false) return t('preview_hidden_on_desktop')
    if (!onDesktop && icon.value.show_on_mobile === false) return t('preview_hidden_on_mobile')
    if (!deviceChannels.value.length) return onDesktop ? t('preview_no_channel_on_desktop') : t('preview_no_channel_on_mobile')
    return ''
})

// Channel whose form the preview shows, as on the site: the one picked in the Customize tab's
// text switch, else the first channel.
const formChannel = computed(() => enabledChannels.value.includes($widget.previewChannel) ? $widget.previewChannel : enabledChannels.value[0])
const telegramConfig = computed(() => $widget.currentWidget?.config?.telegram || {})
const isTelegramForm = computed(() => formChannel.value === 'telegram')
// Off: the site's button has no chat-app icon and reads "Submit".
const redirectsAfterSubmit = computed(() => ($widget.currentWidget?.config?.[formChannel.value] || {}).redirect_after_submit !== false)
// WhatsApp keeps the admin's form colors; Telegram uses its brand color (frontend headerStyle).
const formHeaderStyle = computed(() => isTelegramForm.value
    ? { color: '#ffffff', background: channelColors.telegram }
    : { color: form.value.text_color, background: form.value.background_color })

// reCAPTCHA v2 / Turnstile box above the submit button (built-in form only), as on the site.
// Unsaved changes in the Customize tab first, else the saved settings.
const captchaBox = computed(() => {
    if (form.value.mode !== 'formychat') return ''
    const turnstile = $widget.turnstileOptions || formychat_admin_vars.turnstile || {}
    if (turnstile.enabled && turnstile.site_key) return 'turnstile'
    const recaptcha = $widget.recaptchaOptions || formychat_admin_vars.recaptcha || {}
    if (recaptcha.enabled && recaptcha.site_key && (recaptcha.version || 'v2') === 'v2') return 'recaptcha'
    return ''
})
const launcher = computed(() => $widget.currentWidget?.config?.channels?.launcher || {})
// Editing a channel's description (Channels tab): show the list with descriptions, so the text is
// visible even when the chosen style has none. List style stands in for the others; only the preview changes.
const SUB_STYLES = ['card', 'chat', 'bubble']
const peekStyle = computed(() => $widget.previewPeek && !SUB_STYLES.includes(launcher.value.style))
const listLauncher = computed(() => {
    if (!$widget.previewPeek) return launcher.value
    return { ...launcher.value, style: peekStyle.value ? 'card' : launcher.value.style, show_sub: true }
})
const launcherIcons = formychat_admin_vars.data?.launcher_icons || {}
const launcherIconData = computed(() => launcherIcons[launcher.value.icon] || launcherIcons.chat || {})
const launcherIconUrl = computed(() => launcherIconData.value.url || '')
// Launcher image uploaded in FormyChat Ultimate (2+ channels).
const launcherUpload = computed(() => launcher.value.icon_url || '')
const launcherShape = computed(() => launcherUpload.value ? 'circle' : (launcherIconData.value.shape || 'circle'))
// Same color the site shows (App::resolve_launcher_color()).
const launcherColor = computed(() => resolveLauncherColor(launcher.value, {
    icons: launcherIcons,
    presets: formychat_admin_vars.data?.launcher_colors || [],
    premium: !!formychat_admin_vars.is_premium,
}))
// Launcher symbol color ('' = white, drawn as before). Display only; the site gets it from `formychat_launcher_glyph_color`.
const launcherGlyphColor = computed(() => launcherUpload.value ? '' : resolveLauncherGlyphColor(launcher.value, { presets: formychat_admin_vars.data?.launcher_glyph_colors || [], premium: !!formychat_admin_vars.is_premium }))
const launcherGlyphStyle = computed(() => tintedIconStyle(launcherIconUrl.value, launcherGlyphColor.value))
const showChannelList = ref(true)
// Squircle icons (Sparkle chat) are drawn larger, as on the site (channels.scss).
const launcherIconBox = computed(() => {
    const box = Number(launcherIconData.value.box) || (launcherShape.value === 'squircle' ? 58 : 46)
    return box !== 46 ? { width: box + '%', height: box + '%' } : null
})
// Editing a channel's button text: open the list so each keystroke shows up, and mark that channel.
const focusChannel = computed(() => isMulti.value ? $widget.previewFocus : '')
watch(focusChannel, (channel) => {
    if (!channel) return
    showChannelList.value = true
    showForm.value = false
})
const focusRing = (channel) => focusChannel.value === channel
    ? { outline: '2px dashed #6366F1', outlineOffset: '3px', borderRadius: '9999px' }
    : {}
// List styles with their own preview (not the stack); locked styles preview too.
const ownListStyle = computed(() => ['card', 'row', 'chat', 'grid', 'bubble', 'menu', 'corner'].includes(listLauncher.value.style))
// Channel icon in the list: the channel's color (Channels tab), else its brand color, and its own
// uploaded image when there is one (Telegram: telegram.icon_url; WhatsApp: a custom icon.image_url).
const isBundledImage = url => !url || /\/images\/(whatsapp|telegram)\.svg$/.test(url)
const channelIcon = (channel) => {
    const config = $widget.currentWidget?.config || {}
    const image = channel === 'telegram'
        ? (config.telegram?.icon_url || '')
        : (isBundledImage(config.icon?.image_url) ? '' : config.icon.image_url)
    return {
        color: config[channel]?.icon_color || channelColors[channel],
        glyph: publicUrl + `images/${channel}-glyph.svg`,
        glyphColor: channelGlyphColor(config, channel),
        image,
    }
}
const previewChannels = computed(() => enabledChannels.value.map(channel => ({
    key: channel,
    // Rows always have a name; floating styles hide it when the admin cleared it.
    label: channelRowLabel($widget.currentWidget.config, channel),
    showLabel: channelLabel($widget.currentWidget.config, channel) !== '',
    sub: $widget.currentWidget.config[channel]?.list_sub || '',
    ...channelIcon(channel),
})))

// Same layout and motion as the site's stack (channels.scss): button i (0 = nearest the launcher)
// starts centred on the launcher's box (any shape, pill included) and slides up out of it.
const stackItemStyle = (i) => {
    const size = getSize(icon.value.size, icon.value.size_custom, iconSizes)
    const edge = `calc(50% - ${size} / 2)`
    const left = icon.value.position === 'left'
    return {
        position: 'absolute',
        bottom: edge,
        right: left ? 'auto' : edge,
        left: left ? edge : 'auto',
        gap: '10px',
        pointerEvents: showChannelList.value ? 'auto' : 'none',
        transition: 'transform .5s ease, opacity .5s ease',
        opacity: showChannelList.value ? 1 : 0,
        transform: showChannelList.value ? `translateY(calc(-1 * (${size} + 8px + ${i} * (${size} + 8px))))` : 'translateY(0)',
    }
}
const publicUrl = formychat_admin_vars.public
const singleIconUrl = computed(() => {
    const url = icon.value.image_url || formychat_admin_vars.public + 'images/whatsapp.svg'
    if (enabledChannels.value[0] === 'telegram' && /\/images\/whatsapp\.svg$/.test(url)) {
        return formychat_admin_vars.public + 'images/telegram.svg'
    }
    return url
})
// One channel: the button is that channel's icon (Channels tab). Its own image wins; a picked
// background or icon color draws the glyph on a circle; otherwise the bundled logo, as before.
const singleIcon = computed(() => {
    const channel = enabledChannels.value[0] === 'telegram' ? 'telegram' : 'whatsapp'
    const own = channelIcon(channel)
    if (own.image) return { image: own.image }
    const settings = $widget.currentWidget?.config?.[channel] || {}
    if (isHexColor(settings.icon_color) || isHexColor(settings.glyph_color)) return { color: own.color, glyph: own.glyph, glyphColor: own.glyphColor, channel }
    return { image: singleIconUrl.value }
})

const iconPosition = computed(() => {
    if (icon.value.position !== 'custom') return {};

    return {
        top: icon.value.position_custom?.top ? icon.value.position_custom?.top + 'px !important' : 'auto',
        bottom: icon.value.position_custom?.bottom ? icon.value.position_custom?.bottom + 'px !important' : 'auto',
        left: icon.value.position_custom?.left ? icon.value.position_custom?.left + 'px !important' : 'auto',
        right: icon.value.position_custom?.right ? icon.value.position_custom?.right + 'px !important' : 'auto',
    };
})

const headingSizes = { small: '16px', medium: '18px', large: '20px' }
const textSizes = { small: '12px', medium: '14px', large: '16px' }
const iconSizes = { small: '45px', medium: '60px', large: '80px' }
const formSizes = { small: '280px', medium: '320px', large: '360px' }
// On phones the site opens a multi-channel form full width. Here the content box spans the
// phone frame (less its 8px edges, at the preview's 75% scale) and the form fills it.
const phoneFullForm = computed(() => device.value === 'phone' && isMulti.value)
const formWidth = computed(() => phoneFullForm.value ? '100%' : getSize(form.value.size, form.value.size_custom, formSizes))
const previewFrame = ref(null)
const frameWidth = ref(0)
const frameObserver = typeof ResizeObserver !== 'undefined' ? new ResizeObserver(([entry]) => { frameWidth.value = entry.contentRect.width }) : null
watch(previewFrame, el => { frameObserver?.disconnect(); if (el) frameObserver?.observe(el) }, { immediate: true })
const contentStyle = computed(() => phoneFullForm.value && frameWidth.value
    // !important: the admin's utility classes (w-fit, left/right) are !important too.
    ? { ...iconPosition.value, width: ((frameWidth.value - 16) / 0.75) + 'px !important', [icon.value.position === 'left' ? 'right' : 'left']: 'auto !important' }
    : iconPosition.value)

const getSize = (size, size_custom, options = textSizes) => {
    return options[size] || size_custom + 'px';
}

const state = reactive({
    formLoaded: false,
})

// When to show form.
const showForm = ref(false);
const showGreetings = ref(true);
onMounted(() => {
    window.addEventListener('scroll', () => {
        const customize_form = document.getElementById('customize_form');
        if (customize_form) {
            showForm.value = customize_form.getBoundingClientRect().top < window.innerHeight - 500;
        }
    });

    // On click [data-name] elements.
    document.addEventListener('click', (e) => {
        if (e.target.dataset.name) {
            const targetElement = document.querySelector(`[name="${e.target.dataset.name}"]`)
            if (targetElement) {
                // Scroll to 100px above the element.
                targetElement.scrollIntoView({ behavior: 'smooth', block: 'center', inline: 'nearest' });

                setTimeout(() => {
                    targetElement.focus();
                }, 500)
            }
        }
    })

});

// Greetings handle.
const hideGreetings = () => {
    showGreetings.value = false;

    setTimeout(() => {
        showGreetings.value = true;
    }, 2000)
}

const form_url = computed(() => {
    let id = form.value[form.value.mode + '_id'] || form.value.cf7_id;
    return `${formychat_admin_vars.site.url}/?formychat-form&form=${form.value.mode}&form_id=${id}&admin=true&header=${form.value.subtitle}&footer=${form.value.footer}&widget_id=${$widget.currentWidget.id}`;
})

const iFrame = ref(null)
const adjustHeight = (event) => {
    const iframe = event.target;
    
    if (!iframe) return;
    
    // Set initial styles
    iframe.style.transition = 'height 0.3s ease-in-out';
    iframe.style.maxHeight = '100%';
    iframe.style.height = '0px';
    iframe.style.maxHeight = 'calc(100vh - 180px)';
    
    // Wait for iframe content to be fully loaded
    iframe.addEventListener('load', () => {
        // Get the form element height
        const formElement = iframe.contentWindow.document.body.querySelector('.formychat-custom-form');
        if (!formElement) {
            state.formLoaded = true;  // Using external state object
            return;
        }
        
        const height = formElement.scrollHeight;
        const newHeight = height + 1;
        
        // Apply the new height with animation
        requestAnimationFrame(() => {
            iframe.style.height = `${newHeight}px`;
            iframe.style.maxHeight = `calc(100vh - 180px)`;
        });
        
        // Reset margin on html element if using CF7
        const htmlElement = iframe.contentWindow.document.querySelector('html');
        if (htmlElement) {
            htmlElement.style.margin = '0';
            htmlElement.style.padding = '0';
        }
    });
    
    // Optional: Handle resize events for responsive forms
    const resizeObserver = new ResizeObserver((entries) => {
        const formElement = iframe.contentWindow.document.body.querySelector('.formychat-custom-form');
        if (formElement) {
            const newHeight = formElement.scrollHeight + 1;
            iframe.style.height = `${newHeight}px`;
        }
        
        // Set formLoaded after animation using external state
        setTimeout(() => {
            state.formLoaded = true;
            resizeObserver.disconnect();
        }, 500);
    });
    
    // Start observing the form element for size changes
    const formElement = iframe.contentWindow.document.body.querySelector('.formychat-custom-form');
    if (formElement) {
        resizeObserver.observe(formElement);
    }
    
    // Cleanup function to disconnect observer when needed
    return () => {
        resizeObserver.disconnect();
    };
};

function mergeCustomDropdownIntoFields(baseFields, formConfig) {
    const cd = formConfig?.custom_dropdown
    if (!cd?.enabled || !Array.isArray(cd.options) || !cd.options.length) {
        return baseFields
    }
    const name = cd.name || 'dropdown'
    const selectField = {
        name,
        type: 'select',
        label: cd.label || '',
        default: cd.default_value || '',
        options: cd.options.map((o) => ({ value: o.value, label: o.label })),
        attributes: {
            required: !!cd.required,
            placeholder: cd.placeholder || '',
        },
    }
    const list = [...baseFields]
    const pos = cd.position || 'before_message'
    let insertAt = list.length
    if (pos === 'before_message') {
        const i = list.findIndex((f) => f.name === 'message')
        insertAt = i === -1 ? list.length : i
    } else if (pos === 'after_name') {
        const i = list.findIndex((f) => f.name === 'name')
        insertAt = i === -1 ? list.length : i + 1
    } else if (pos === 'after_email') {
        const i = list.findIndex((f) => f.name === 'email')
        insertAt = i === -1 ? list.length : i + 1
    } else if (pos === 'after_phone') {
        const i = list.findIndex((f) => f.name === 'phone')
        insertAt = i === -1 ? list.length : i + 1
    }
    list.splice(insertAt, 0, selectField)
    return list
}

// Form Fields (merge per-widget custom dropdown for FormyChat).
const fields = computed(() => {
    const base = formychat_admin_vars.data.form_fields || []
    if (form.value.mode !== 'formychat') {
        return base
    }
    return mergeCustomDropdownIntoFields(base, form.value)
})
</script>
<template>
    <div class="w-full max-w-[480px] flex-col gap-3 items-center z-20 relative">
        <!-- mobile save buttons  -->
        <div class="flex sm:hidden items-center mt-5 mb-10 w-full sm:w-fit gap-6 sm:justify-end sm:gap-2 z-20 bg-white"
            :class="{ 'justify-end': $widget.isTab('channels'), 'justify-between': !$widget.isTab('channels') }">
            <Button v-if="!$widget.isTab('channels')" outline @click="$widget.prevTab()">{{ $widget.isTab('channels') ?
                t('cancel') : '← ' + t('previous') }}</Button>
            <Button @click="$widget.isTab('triggers') ? $widget.saveWidget() : $widget.nextTab()">{{
                $widget.isTab('triggers') ? $widget.currentWidget.isNew ? '☁ ' + t('create') : '☁ ' + t('save') : t('next') + ' →' }}</Button>
        </div>
        <div class="w-full space-y-6"
            :class="{ 
                'md:sticky md:top-[7rem]': $widget.isTab('customize') || ($widget.isTab('channels') && (whatsapp.agent_mode === 'agents' || isMulti)) || ($widget.isTab('greetings') && $widget.currentWidget.config.greetings.enabled),
                'z-0' : showForm
            }">
            <div ref="previewFrame" class="border sm:min-h-[18rem] md:min-h-[20rem] xl:min-h-[22rem] border-slate-200 rounded shadow-sm mx-auto relative bg-gray-50"
                :class="{ 'w-phone': device === 'phone', 'w-desktop': device === 'desktop' }">
                <!-- header dots  -->
                <div
                    class="bg-slate-50 border-b border-slate-200 h-8 flex items-center gap-2 child:w-3 child:h-3 child:rounded-full px-3">
                    <span class="bg-red-400"></span>
                    <span class="bg-yellow-400"></span>
                    <span class="bg-green-400"></span>
                </div>
                <!-- Previewing in List style while a description is edited: say so -->
                <transition name="fade">
                    <div v-if="peekStyle && isMulti" class="absolute top-10 left-3 right-3 z-30 flex pointer-events-none" role="status">
                        <div class="w-full flex items-center gap-2.5 px-3 py-2 rounded-lg border border-indigo-100 bg-white shadow-sm">
                            <span class="w-6 h-6 rounded-md bg-indigo-50 text-indigo-600 grid place-items-center shrink-0" aria-hidden="true">
                                <svg viewBox="0 0 24 24" class="w-3.5 h-3.5" fill="none" stroke="currentColor" stroke-width="2.2" stroke-linecap="round" stroke-linejoin="round"><path d="M2 12s3.5-7 10-7 10 7 10 7-3.5 7-10 7S2 12 2 12Z" /><circle cx="12" cy="12" r="3" /></svg>
                            </span>
                            <span class="flex flex-col min-w-0" style="line-height: 1.35;">
                                <span class="text-xs font-semibold text-slate-900">{{ t('preview_peek_title') }}</span>
                                <!-- One line; the phone view cuts it with an ellipsis (full text on hover) -->
                                <span class="text-slate-500 truncate" style="font-size: 11px;" :title="t('preview_peek_hint')">{{ t('preview_peek_hint') }}</span>
                            </span>
                        </div>
                    </div>
                </transition>
                <!-- The site shows no widget on this device: say why, and keep the widget faded behind -->
                <div v-if="hiddenReason" class="absolute inset-x-0 top-8 bottom-0 z-30 grid place-items-center p-4 pointer-events-none">
                    <span class="inline-flex items-center gap-1.5 px-3 py-1.5 rounded-full bg-slate-800 text-white text-xs font-medium shadow">
                        <svg viewBox="0 0 24 24" class="w-3.5 h-3.5" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M3 3l18 18M10.6 10.6a2 2 0 0 0 2.8 2.8M9.9 5.1A9.8 9.8 0 0 1 12 5c5 0 9 4.5 10 7a13 13 0 0 1-3 4.2M6.1 6.1A13 13 0 0 0 2 12c1 2.5 5 7 10 7a9.6 9.6 0 0 0 4.4-1" /></svg>
                        {{ hiddenReason }}
                    </span>
                </div>
                <!-- content  -->
                <div class="absolute flex flex-col gap-3 w-fit scale-75 transition-opacity"
                    :class="{
                        'opacity-25': !!hiddenReason,
                        'bottom-2 right-2 items-end origin-bottom-right': icon.position === 'right', 
                        'bottom-2 left-2 items-start origin-bottom-left': icon.position === 'left',
                        'origin-bottom-center': icon.position === 'custom'
                        }"
                    :style="contentStyle">
                    <!-- form  -->
                    <transition name="form_slide">
                        <div v-if="(showForm && $widget.isTab('customize')) || ($widget.isTab('channels') && whatsapp.agent_mode === 'agents' && enabledChannels.includes('whatsapp'))"
                            class="formychat-widget-form  max-h-[19rem] overflow-scroll transition-all" :style="{
                                fontFamily: !form.font_family || form.font_family == 'sans-serif' ? '-apple-system, sans-serif' : form.font_family,
                                width: formWidth,
                            }">
                            <!-- header   -->
                            <div class="formychat-widget-form-title" :style="formHeaderStyle">
                                <span>
                                    <!-- Telegram's own title (empty = the main form title), as on the site -->
                                    <Editable v-if="isTelegramForm" v-model="telegramConfig.form_title" :placeholder="form.title || t('contact_via_telegram')"
                                        data-name="telegram_form_title" />
                                    <Editable v-else v-model="form.title" :placeholder="t('contact_via_whatsapp')"
                                        data-name="form_title" />
                                </span>
                                <div>
                                    <svg xmlns="http://www.w3.org/2000/svg" @click="showForm = false"
                                        viewBox="0 0 16 16">
                                        <path fill-rule="evenodd"
                                            d="M1.646 4.646a.5.5 0 0 1 .708 0L8 10.293l5.646-5.647a.5.5 0 0 1 .708.708l-6 6a.5.5 0 0 1-.708 0l-6-6a.5.5 0 0 1 0-.708" />
                                    </svg>
                                </div>
                            </div>
                            <!-- header  -->
                            <transition name="slide">
                                <div class="formychat-header px-5 pt-3" v-if="form.mode === 'formychat' && form.subtitle">
                                    <Editable v-model="form.subtitle" data-name="form_subtitle" />
                                </div>
                            </transition>
                            <!-- agents  -->
                            <div class="formychat-widget-agents"
                                v-if="whatsapp.agent_mode === 'agents' && $widget.isTab('channels')">
                                <div v-if="whatsapp.agents.length" v-for="agent in whatsapp.agents"
                                    class="formychat-widget-agents-agent">
                                    <div class="formychat-widget-agents-agent-picture">
                                        <img :src="agent.avatar">
                                    </div>
                                    <div class="formychat-widget-agents-name">
                                        <div class="font-semibold text-[15px]">
                                            <Editable v-model="agent.name" data-name="agent_name" :placeholder="t('agent_name')" />
                                        </div>
                                        <div class="text-[12px] text-slate-400">
                                            <Editable v-model="agent.subtitle" data-name="agent_subtitle" :placeholder="t('agent_subtitle')" />
                                        </div>
                                    </div>
                                </div>
                                <div v-else
                                    class="bg-yellow-50 border border-yellow-200 px-6 py-4 rounded text-yellow-500 text-center">
                                    {{ t('create_your_first_agent') }}</div>
                            </div>
                            <!-- Form mode formychat  -->
                            <div v-if="form.mode === 'formychat' && (showForm && $widget.isTab('customize'))">
                                <!-- FORMYCHAT Content  -->
                                <div class="formychat-widget-form-fields" style="width: 100% !important;">
                                    <fieldset v-for="field in fields" :key="field.name">

                                        <!-- label  -->
                                        <label v-if="field.label" :for="field.name" class="formychat-widget-form-fields-label">
                                            {{ field.label }}
                                        </label>

                                        <!-- Text, Email, Password, Date, Number, Tel, Url, Color, Range, Search, Time, Week, Month, Image, File, Submit -->
                                        <input
