<script setup>
import { computed } from 'vue';
import { CHANNELS, CHANNEL_COLORS } from '../utility/channels';

const props = defineProps({
	// whatsapp | telegram. Empty or unknown (leads saved before channels existed) shows WhatsApp.
	channel: { type: String, default: 'whatsapp' },
	// Circle diameter in px. The glyph is half of it.
	size: { type: Number, default: 28 },
	// Tooltip and accessible name. Defaults to the channel name.
	title: { type: String, default: '' },
	// Hide from screen readers when the channel name is printed next to the icon.
	decorative: { type: Boolean, default: false },
});

const NAMES = { whatsapp: 'WhatsApp', telegram: 'Telegram' };

const key = computed(() => (CHANNELS.includes(props.channel) ? props.channel : 'whatsapp'));
const label = computed(() => props.title || NAMES[key.value]);
const glyph = computed(() => (window.formychat_admin_vars?.public || '') + `images/${key.value}-glyph.svg`);
const glyphSize = computed(() => Math.round(props.size / 2) + 'px');
</script>
<template>
	<span
		class="rounded-full grid place-items-center shrink-0"
		:style="{ width: size + 'px', height: size + 'px', background: CHANNEL_COLORS[key] }"
		:title="decorative ? null : label"
		:role="decorative ? null : 'img'"
		:aria-label="decorative ? null : label"
		:aria-hidden="decorative ? 'true' : null">
		<img :src="glyph" :style="{ width: glyphSize, height: glyphSize }" alt="">
	</span>
</template>
