/**
 * The editor shows a widget the way the site shows it.
 *
 * PHP sends `site_config`: the saved config after `formychat_widget_config`, which turns
 * options this site does not offer (for example FormyChat Ultimate styles while it is
 * inactive) back to their defaults. The editor and preview show those values, while the
 * saved ones are kept aside and written back on save unless the admin picked something
 * else. So nothing saved is lost, and the saved choices come back once the site offers
 * them again.
 *
 * @since 2.16.0
 */

const isPlainObject = value => value !== null && typeof value === 'object' && !Array.isArray(value)
const copy = value => (value === undefined ? undefined : JSON.parse(JSON.stringify(value)))

// Same value, allowing for '1' vs 1 between PHP and JS.
export const sameValue = (a, b) => {
    if (JSON.stringify(a) === JSON.stringify(b)) return true
    const scalar = v => v === null || ['string', 'number', 'boolean'].includes(typeof v)
    return scalar(a) && scalar(b) && String(a) === String(b)
}

const getPath = (object, path) => path.reduce((node, key) => (isPlainObject(node) ? node[key] : undefined), object)

const setPath = (object, path, value) => {
    let node = object
    for (let i = 0; i < path.length - 1; i++) {
        if (!isPlainObject(node[path[i]])) return
        node = node[path[i]]
    }
    node[path[path.length - 1]] = value
}

/**
 * Show the site's values in `config` (changed in place) and list the saved values they replace.
 *
 * @param {object} config     Saved config (normalized), edited in place.
 * @param {object} siteConfig Config as the site shows it.
 * @returns {Array<{path: string[], saved: *, shown: *}>}
 */
export const applySiteConfig = (config, siteConfig) => {
    const hidden = []
    if (!isPlainObject(config) || !isPlainObject(siteConfig)) return hidden

    const walk = (saved, site, path) => {
        Object.keys(site).forEach(key => {
            if (!(key in saved)) return
            const next = [...path, key]
            if (isPlainObject(saved[key]) && isPlainObject(site[key])) {
                walk(saved[key], site[key], next)
            } else if (!sameValue(saved[key], site[key])) {
                hidden.push({ path: next, saved: copy(saved[key]), shown: copy(site[key]) })
                saved[key] = copy(site[key])
            }
        })
    }
    walk(config, siteConfig, [])

    return hidden
}

/**
 * Config to save: a value the admin left as shown goes back to its saved value.
 *
 * @param {object} config Config in the editor.
 * @param {Array}  hidden List from applySiteConfig().
 * @returns {object} A copy; the editor's config is not changed.
 */
export const restoreSavedValues = (config, hidden = []) => {
    const out = copy(config)
    hidden.forEach(({ path, saved, shown }) => {
        if (sameValue(getPath(out, path), shown)) setPath(out, path, copy(saved))
    })
    return out
}

/**
 * After a save: drop entries the admin changed (their new value is now the saved one).
 */
export const keepUntouched = (config, hidden = []) => hidden.filter(({ path, shown }) => sameValue(getPath(config, path), shown))
