const defaultConfig = {
    isNew: true,
    name: `Widget ${Number( formychat_admin_vars.total.widgets ) + 1}`,
    is_active: true,
    config: formychat_admin_vars.data.widget_config || {},
}

// Fast path only. At module-eval time the IP lookup is usually still in flight,
// so this often sets the fallback. WhatsApp.vue and the widgets store await
// window.formychat_country_code_ready and backfill the real value.
if ( defaultConfig.config.whatsapp && ! defaultConfig.config.whatsapp.country_code ) {
    defaultConfig.config.whatsapp.country_code = String( window.formychat_country_code || '44' )
}

export default defaultConfig
