<script setup>
import { computed, ref, watch } from 'vue';
import { useWidgets } from '@store/widgets';
import { useTranslation } from '../../../composables/useTranslation';
import { ChannelGlyph } from '@components';
import { channelGlyphColor, channelIconColor, savedChannelImage } from '../../../utility/channels';

const props = defineProps({
    channel: { type: String, required: true },
    index: { type: Number, default: 0 },
    total: { type: Number, default: 1 },
    // Advanced options panel.
    open: { type: Boolean, default: false },
    // Drop target highlight while another card is dragged over this one.
    dropTarget: { type: Boolean, default: false },
})

const emit = defineEmits(['update:open', 'remove', 'move', 'dragstart', 'dragend'])

const $widget = useWidgets();
const { t } = useTranslation();

const names = { whatsapp: 'WhatsApp', telegram: 'Telegram' }
const settings = computed(() => $widget.currentWidget?.config?.[props.channel] || {})
// The channel's chosen icon and color (Settings > Icon / Color).
const iconImage = computed(() => savedChannelImage($widget.currentWidget?.config, props.channel))
const iconColor = computed(() => channelIconColor($widget.currentWidget?.config, props.channel))
const glyphColor = computed(() => channelGlyphColor($widget.currentWidget?.config, props.channel))
const panelId = computed(() => `formychat-channel-panel-${props.channel}`)

// The panel clips its content only while it animates, so tooltips inside an open panel are not cut off.
const settled = ref(props.open)
watch(() => props.open, () => { settled.value = false })
const onPanelTransitionEnd = (event) => {
    if (event.target === event.currentTarget && props.open) settled.value = true
}
</script>
<template>
    <section class="formychat-channel-card group/card relative rounded-2xl border bg-white transition-[border-color,box-shadow] duration-200"
        :class="dropTarget ? 'border-indigo-400 ring-4 ring-indigo-500/10' : 'border-slate-200 hover:border-slate-300 shadow-[0_1px_2px_rgba(15,23,42,0.04)]'"
        :aria-label="names[channel]">

        <div class="flex gap-3 p-4 pb-3 sm:gap-4 sm:p-5 sm:pb-4">
            <!-- Drag handle  -->
            <button v-if="total > 1" type="button" draggable="true"
                class="-ml-2 mt-2.5 w-5 h-7 shrink-0 grid place-items-center rounded text-slate-300 hover:text-slate-500 cursor-grab active:cursor-grabbing"
                :title="t('drag_to_reorder')" :aria-label="t('drag_to_reorder')"
                @dragstart="emit('dragstart', $event)" @dragend="emit('dragend')"
                @keydown.up.prevent="emit('move', -1)" @keydown.down.prevent="emit('move', 1)">
                <svg viewBox="0 0 16 16" class="w-3.5 h-3.5 fill-current" aria-hidden="true">
                    <circle cx="5.5" cy="3" r="1.4" /><circle cx="10.5" cy="3" r="1.4" />
                    <circle cx="5.5" cy="8" r="1.4" /><circle cx="10.5" cy="8" r="1.4" />
                    <circle cx="5.5" cy="13" r="1.4" /><circle cx="10.5" cy="13" r="1.4" />
                </svg>
            </button>

            <!-- Channel icon  -->
            <span class="w-9 h-9 sm:w-11 sm:h-11 rounded-full grid place-items-center shrink-0 shadow-sm overflow-hidden" :style="iconImage ? {} : { background: iconColor }">
                <img v-if="iconImage" :src="iconImage" class="w-full h-full object-cover" alt="">
                <ChannelGlyph v-else :channel="channel" :color="glyphColor" class="w-6 h-6" />
            </span>

            <div class="flex-1 min-w-0 flex flex-col gap-3">
                <!-- Title row  -->
                <div class="flex items-center gap-2 min-h-[28px]">
                    <h3 class="m-0 min-w-0 truncate text-[15px] font-semibold text-slate-900 leading-tight">{{ names[channel] }}</h3>
                    <span v-if="total > 1" class="shrink-0 text-[11px] font-medium text-slate-500 bg-slate-100 rounded-full px-2 h-5 inline-flex items-center">#{{ index + 1 }}</span>

                    <div class="ml-auto shrink-0 flex items-center gap-0.5">
                        <button v-if="total > 1" type="button" :disabled="index === 0"
                            class="w-7 h-7 grid place-items-center rounded-md text-slate-400 hover:text-slate-700 hover:bg-slate-100 disabled:opacity-30 disabled:pointer-events-none opacity-0 group-hover/card:opacity-100 focus-visible:opacity-100 transition"
                            :title="t('move_up')" :aria-label="t('move_up')" @click="emit('move', -1)">
                            <svg viewBox="0 0 24 24" class="w-4 h-4" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="m18 15-6-6-6 6" /></svg>
                        </button>
                        <button v-if="total > 1" type="button" :disabled="index === total - 1"
                            class="w-7 h-7 grid place-items-center rounded-md text-slate-400 hover:text-slate-700 hover:bg-slate-100 disabled:opacity-30 disabled:pointer-events-none opacity-0 group-hover/card:opacity-100 focus-visible:opacity-100 transition"
                            :title="t('move_down')" :aria-label="t('move_down')" @click="emit('move', 1)">
                            <svg viewBox="0 0 24 24" class="w-4 h-4" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="m6 9 6 6 6-6" /></svg>
                        </button>
                        <button type="button"
                            class="w-7 h-7 grid place-items-center rounded-md text-slate-400 hover:text-red-600 hover:bg-red-50 transition"
                            :title="t('remove_channel')" :aria-label="t('remove_channel')" @click="emit('remove')">
                            <svg viewBox="0 0 24 24" class="w-4 h-4" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">
                                <path d="M3 6h18" /><path d="M19 6v14a2 2 0 0 1-2 2H7a2 2 0 0 1-2-2V6" /><path d="M8 6V4a2 2 0 0 1 2-2h4a2 2 0 0 1 2 2v2" />
                                <path d="M10 11v6" /><path d="M14 11v6" />
                            </svg>
                        </button>
                    </div>
                </div>

                <!-- Main value (number, username, agents)  -->
                <slot name="primary" />

                <!-- Toolbar  -->
                <div class="flex flex-wrap items-center gap-2 pt-1">
                    <span class="text-[13px] text-slate-500 mr-0.5">{{ t('show_on') }}</span>
                    <div class="inline-flex rounded-lg border border-slate-200 bg-slate-50 p-0.5" role="group" :aria-label="t('show_on')">
                        <button type="button" class="w-8 h-7 grid place-items-center rounded-md transition"
                            :class="settings.show_on_desktop ? 'bg-white text-indigo-600 shadow-sm ring-1 ring-slate-200' : 'text-slate-400 hover:text-slate-600'"
                            :aria-pressed="settings.show_on_desktop ? 'true' : 'false'" :title="t('desktop')" :aria-label="t('desktop')"
                            @click="settings.show_on_desktop = !settings.show_on_desktop">
                            <svg viewBox="0 0 24 24" class="w-4 h-4" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">
                                <rect x="3" y="4" width="18" height="12" rx="2" /><path d="M2 20h20" />
                            </svg>
                        </button>
                        <button type="button" class="w-8 h-7 grid place-items-center rounded-md transition"
                            :class="settings.show_on_mobile ? 'bg-white text-indigo-600 shadow-sm ring-1 ring-slate-200' : 'text-slate-400 hover:text-slate-600'"
                            :aria-pressed="settings.show_on_mobile ? 'true' : 'false'" :title="t('mobile')" :aria-label="t('mobile')"
                            @click="settings.show_on_mobile = !settings.show_on_mobile">
                            <svg viewBox="0 0 24 24" class="w-4 h-4" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">
                                <rect x="6" y="2" width="12" height="20" rx="2" /><path d="M11 18h2" />
                            </svg>
                        </button>
                    </div>

                    <slot name="toolbar" />

                    <button type="button"
                        class="inline-flex items-center gap-1.5 h-8 px-3 rounded-lg border text-[13px] font-medium transition"
                        :class="open ? 'border-indigo-200 bg-indigo-50 text-indigo-700' : 'border-slate-200 bg-white text-slate-600 hover:border-slate-300 hover:text-slate-800'"
                        :aria-expanded="open ? 'true' : 'false'" :aria-controls="panelId" @click="emit('update:open', !open)">
                        <svg viewBox="0 0 24 24" class="w-4 h-4" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">
                            <path d="M20 7h-9" /><path d="M14 17H5" /><circle cx="17" cy="17" r="3" /><circle cx="7" cy="7" r="3" />
                        </svg>
                        {{ t('channel_settings') }}
                        <svg viewBox="0 0 24 24" class="w-3.5 h-3.5 transition-transform duration-200" :class="{ 'rotate-180': open }" fill="none" stroke="currentColor" stroke-width="2.25" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">
                            <path d="m6 9 6 6 6-6" />
                        </svg>
                    </button>
                </div>
            </div>
        </div>

        <!-- Advanced options; height animates through the grid row  -->
        <div :id="panelId" class="grid transition-[grid-template-rows] duration-300 ease-out"
            :class="open ? 'grid-rows-[1fr]' : 'grid-rows-[0fr]'" :inert="!open || undefined"
            @transitionend="onPanelTransitionEnd">
            <div :class="open && settled ? 'overflow-visible' : 'overflow-hidden'">
                <!-- Left padding lines the panel up with the content column (grip + icon + gaps).  -->
                <div class="border-t border-slate-100 bg-slate-50/50 rounded-b-2xl px-5 py-5 flex flex-col gap-6" :class="total > 1 ? 'sm:pl-[108px]' : 'sm:pl-[80px]'">
                    <slot name="advanced" />
                </div>
            </div>
        </div>
    </section>
</template>
