<script setup>
import { ref } from 'vue';
import { useTranslation } from '../composables/useTranslation';

const { t } = useTranslation();
const props = defineProps({
    title: {
        type: String,
        default: 'Title'
    },
    gap: {
        type: Boolean,
        default: true
    }
})
const isOpen = ref( true );

// Unique id so the toggle can point at the panel it controls.
const panelId = `formychat-group-${Math.random().toString(36).slice(2, 9)}`;

</script>

<template>
    <div class="flex flex-col gap-3">
        <div class="flex items-center justify-between">
            <h3 class="font-bold text-base text-gray-700 tracking-wide border-l-4 pl-3 border-indigo-600">
                <slot name="title" v-if="$slots.title" />
                <span v-else>{{props.title}}</span>
            </h3>
            <button type="button" @click="isOpen = !isOpen" :aria-expanded="isOpen ? 'true' : 'false'" :aria-controls="panelId"
                :aria-label="isOpen ? t('collapse_section') : t('expand_section')" :title="isOpen ? t('collapse_section') : t('expand_section')"
                class="w-8 h-8 shrink-0 grid place-items-center rounded-full border transition duration-200 focus:outline-none focus-visible:ring-2 focus-visible:ring-indigo-500 focus-visible:ring-offset-2"
                :class="isOpen ? 'border-slate-200 bg-white text-slate-500 hover:border-indigo-300 hover:bg-indigo-50 hover:text-indigo-600' : 'border-indigo-200 bg-indigo-50 text-indigo-600 hover:border-indigo-300 hover:bg-indigo-100'">
                <svg viewBox="0 0 24 24" class="w-4 h-4 transition-transform duration-200" :class="{ 'rotate-180': isOpen }" fill="none" stroke="currentColor" stroke-width="2.25" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">
                    <path d="m6 9 6 6 6-6" />
                </svg>
            </button>
        </div>
        <transition name="slide">
            <div v-if="isOpen" :id="panelId" class="rounded-sm flex flex-col gap-5" :class="{
                'bg-slate-50 p-5' : props.gap,
            }" v-bind="$attrs">
<slot></slot>            </div>
        </transition>
    </div>
</template>